  ('4d00b12e-9ccb-5c7c-9873-3ca738cca0a0', '22222222-2222-2222-2222-222222222201', 'short', '迪丽热巴没有钱。F', null, '', '', '逻辑/基础必修1-选言命题、联言命题.pdf', 5, true, 11, null),
  ('4dda7c5a-2d71-5a50-ac25-db9488fc64a4', '22222222-2222-2222-2222-222222222201', 'short', '迪丽热巴腿长。? 模块一 形式逻辑 专题一 复合命题 考点一 联言命题 五、矛盾命题 并非+原命题=矛盾命题 联言命题P∧Q表示P、Q都为真， 所以与其矛盾的情况有三种可能性：', null, '', '', '逻辑/基础必修1-选言命题、联言命题.pdf', 5, true, 12, null),
  ('e00855af-c655-5603-979b-66626b3d88da', '22222222-2222-2222-2222-222222222201', 'short', 'P为真，Q为假。', null, '', '', '逻辑/基础必修1-选言命题、联言命题.pdf', 6, true, 13, null),
