  ('3bfd28d6-e336-529f-8c6f-8a7ebef51898', '22222222-2222-2222-2222-222222222203', 'short', '并非所有地铁都在地下开。 =有的地铁不在地下开。', null, '', '', '逻辑/基础必修3-简单命题1.pdf', 23, true, 37, null),
