  ('7cc7e8e9-2bae-5ba1-a78b-184c1dc8a615', '22222222-2222-2222-2222-222222222203', 'short', '优秀企业家→果敢∧有头脑；', null, '', '', '逻辑/基础必修4-概念.pdf', 33, true, 145, null),
  ('e0cc5e99-3683-5916-b199-6ad531116a95', '22222222-2222-2222-2222-222222222203', 'short', '公司长久→果敢∧有头脑。 第二步，验证选项： A、C选项：公司长久→优秀企业家，这两项无法由题干信息推出，不一定为真，排除。 B选项：有些果敢∧有头脑→¬优秀企业家，由（3）可推出，有些果敢∧有头脑→优秀企业家，根据下反对关 系可知，该项不一定为真，排除。 D选项：有些果敢∧有头脑→¬大学教育，结合（1）（3）可推出，有些¬大学教育→优秀企业家→果敢∧有头 脑=有些果敢∧有头脑→¬大学教育，该项一定为真。 E选项：多数大学教育→果敢∧有头脑，“多数”无法和“有些”一样做位置互换，所以无法结合（2）（3） 推出该项，排除。故正确答案为D选项。 模块一 形式逻辑 练习 一、概念', null, '', '', '逻辑/基础必修4-概念.pdf', 33, true, 146, null),
  ('ea73cf85-5379-5fb8-9f63-700659d6483e', '22222222-2222-2222-2222-222222222203', 'short', '集合概念和非集合概念的分辨 分辨方法：', null, '', '', '逻辑/基础必修4-概念.pdf', 34, true, 147, null),
  ('91b1c508-3c2b-5f3c-9b21-50cb2eff1698', '22222222-2222-2222-2222-222222222203', 'short', '“所有A是B”的涵义是否等价于“每一个A都是B”？ 若是，则A是非集合概念；若不是，则A是集合概念。', null, '', '', '逻辑/基础必修4-概念.pdf', 34, true, 148, null),
  ('1f7ee521-ed39-591b-b158-eb2205bd4d65', '22222222-2222-2222-2222-222222222203', 'short', '前加“每一个”或后加“之一”，加上之后句意不变就是非集合概念，加上之后句意 改变就是集合概念。 重点内容总结 重点内容总结 一、概念', null, '', '', '逻辑/基础必修4-概念.pdf', 34, true, 149, null),
  ('6acbb632-f458-59f8-a36b-cbbfbb1d21c4', '22222222-2222-2222-2222-222222222203', 'mcq', '概念之间的关系 概念关系 相容关系 不相容关系 示例 全同关系 属种关系 交叉关系 矛盾关系 反对关系 真包含关系 真包含于关系 图示', '[{"key": "A", "text": "北京"}, {"key": "B", "text": "中国首都"}, {"key": "A", "text": "中国的岛屿"}, {"key": "B", "text": "南沙群岛"}, {"key": "A", "text": "大学生"}, {"key": "B", "text": "学生"}, {"key": "A", "text": "大学生"}, {"key": "B", "text": "共产党 员"}, {"key": "A", "text": "红色"}, {"key": "B", "text": "非红色"}, {"key": "A", "text": "红色"}, {"key": "B", "text": "绿色 感谢您的聆听 课后练习： 小程序-管综（逻辑）-章节训练-形式逻辑（简单命题）"}]'::jsonb, '', '', '逻辑/基础必修4-概念.pdf', 35, true, 150, null),
  ('9c3e2859-17db-522d-9884-9ff69b773c99', '22222222-2222-2222-2222-222222222204', 'short', '如果张明报名，则刘伟也报名。', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 3, true, 1, null),
  ('32b0cb24-73a9-5d2c-88a6-6a495c3da8ac', '22222222-2222-2222-2222-222222222204', 'short', '如果庄敏报名，则孙兰也报名。', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 3, true, 2, null),
  ('d55bac25-50c4-5a7e-b0cf-f49220868c49', '22222222-2222-2222-2222-222222222204', 'mcq', '只要刘伟和孙兰2人中至少有1人报名，则李梅也 报名。（均为假言命题） 后来得知，他们5人中恰有3人报名了。（数量关系） 根据以上信息，可以得出以下哪项?', '[{"key": "A", "text": "张明报名了。"}, {"key": "B", "text": "刘伟报名了。"}, {"key": "C", "text": "庄敏报名了。 均为事实"}, {"key": "D", "text": "孙兰报名了。"}, {"key": "E", "text": "李梅报名了。 【例题2】 老李在兰花、罗汉松、金桔、牡丹、茶花这5个盆栽 中选购了3个（数量关系）放在家中观赏。老李对选 购的盆栽有如下要求:"}]'::jsonb, '', '', '逻辑/基础必修5-综合推理1.pdf', 3, true, 3, null),
  ('b5ccd84b-746d-58e6-a3ba-5c128cb4ae57', '22222222-2222-2222-2222-222222222204', 'short', '如果选购兰花，就选购罗汉松。', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 3, true, 4, null),
  ('87538e05-f8a7-5868-872b-cd7701edba40', '22222222-2222-2222-2222-222222222204', 'mcq', '如果选购牡丹，就选购罗汉松和茶花。 （均为假言命题） 根据上述信息，老李一定选购了如下哪个盆栽?', '[{"key": "A", "text": "兰花。"}, {"key": "B", "text": "罗汉松。"}, {"key": "C", "text": "金桔。 均为事实"}, {"key": "D", "text": "牡丹。"}, {"key": "E", "text": "茶花。"}]'::jsonb, '', '', '逻辑/基础必修5-综合推理1.pdf', 3, true, 5, null),
  ('01f8e6e1-64a1-5ea0-99b4-6430c727d261', '22222222-2222-2222-2222-222222222204', 'short', '张明→刘伟。', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 4, true, 6, null),
  ('f31218c0-ffcf-5124-a528-1480234fb482', '22222222-2222-2222-2222-222222222204', 'short', '庄敏→孙兰。', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 4, true, 7, null),
  ('67ececce-ebdc-56da-8c19-42d04b91e69b', '22222222-2222-2222-2222-222222222204', 'short', '刘伟∨孙兰→李梅。 由（1）、（3）串联可得:张明→刘伟→李梅，逆否 可得:¬李梅→¬刘伟→¬张明。 可见，若李梅不报名，则刘伟和张明也不报名， 此时最多有2人报名，与“5人中恰有3人报名”矛 盾，即:由“¬李梅”出发推出了矛盾，故“¬李梅” 为假，即“李梅”为真。 因此，E项正确。 【例题2解析】', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 4, true, 8, null),
  ('d5d7b0ea-a6c9-5e79-874e-435587f70773', '22222222-2222-2222-2222-222222222204', 'short', '兰花→罗汉松。', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 4, true, 9, null),
  ('bb8e043e-9eae-5b6c-897b-5e35a4fc3240', '22222222-2222-2222-2222-222222222204', 'short', '牡丹→罗汉松∧茶花。 “罗汉松”出现多次，故优先分析。 由（1）可知，¬罗汉→¬兰花。 由（2）可知，¬罗汉→¬牡丹。 可见，如果不选购罗汉松，那么也不选购兰花和 牡丹，此时最多选购2个盆栽，与“在5个盆栽中选 购了3个"矛盾，故“不选购罗汉松"为假，即:选购罗 汉松。 因此，B项正确。 二、综合推理题的解题思路 只要已知条件的构成形式是相同的，那么解题思路就是相同的。 第一步：通过已知条件，识别母题模型； 第二步：套用母题解题方法。 5大条件的识别', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 4, true, 10, null),
  ('4d4cccf8-7e86-5796-bcb7-f14052b363a1', '22222222-2222-2222-2222-222222222204', 'short', '事实 即题干中给出的确定信息。如:北门种桃树;张三没有考上研究生;李四与王五相邻等。', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 5, true, 11, null),
  ('a3cf3603-d317-5db9-955c-b3e9ee399046', '22222222-2222-2222-2222-222222222204', 'short', '半事实 即题干中给出的情况较少的信息。如:张三∨李四;王五要么报考清华大学，要么报考北京大学等。', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 5, true, 12, null),
  ('e9bb2d49-9555-5474-9df1-dd92fd166d67', '22222222-2222-2222-2222-222222222204', 'short', '假言（→） 即题干中给出的假言命题。从近5年的逻辑真题命题来看，多数综合推理题中都会出现假言命题。 当然，如果题干中出现“所有A都是B"等能画成箭头的其他条件，也可以近似地认为是假言条件。', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 5, true, 13, null),
  ('2c8e196c-0686-533b-8ea2-f5c751425556', '22222222-2222-2222-2222-222222222204', 'short', '匹配 即题干中给出的对应关系。如:4个人分别报考4所大学中的一所;5种不同的树分别种在5个不同的 园区等。 在匹配题中还常出现“互斥条件”，即题干中给出互相排斥的信息。如:已知数学老师只有一位， 而张珊与数学老师一起吃过饭，则张珊不是数学老师。即“张珊”与“数学老师”存在互斥关系。', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 5, true, 14, null),
  ('7f2d8f8a-7743-5cea-910a-1b525173796f', '22222222-2222-2222-2222-222222222204', 'short', '数量 即题干中给出的数量关系。如：7个人中有5人入选等。 三、已知条件的分类 5大条件的识别 母题模型一 事实假言模型 （一）基本型：事实假言模型 4大核心母题题型（5大条件类） 第一步： 识别命题形式', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 5, true, 15, null),
  ('156f9822-c8a8-5268-bc3e-373b2420e4cd', '22222222-2222-2222-2222-222222222204', 'short', '题干特点 题干中的已知条件主要由5大条件中的“事实”和“假言命题”组成。 注意:“事实”可能出现在已知条件中，也可能补充在提问中。若事实补充在提问中， 一般可优先从提问中的事实出发来解题。', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 6, true, 16, null),
  ('a3db1cb7-f70c-5011-b1f3-041474bad243', '22222222-2222-2222-2222-222222222204', 'short', '选项特点 题干中的选项均为事实或多为事实。 第二步： 套用母题方法 事实出发法 从事实出发，根据口诀“肯前必肯后，否后必否前”可以直接推出答案。 此方法的原理为:已知:A→B→C。 若已知A为真(肯前)，则必能推出C为真(肯后)。 逆否可知，上述条件等价于:¬C→¬B→¬A。 故，若已知C为假(否后)，则必能推出A为假(否前)。 口诀：题干事实加假言，事实出发做串联；肯前必肯后，否后必否前。 【例1】 某科研单位有赵嘉、钱宜、孙斌、李思、周武、 吴纪六名顶级专家。该单位的一名或多名专家参与一 项科研攻坚任务。已知:', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 6, true, 17, null),
  ('8d51cf3e-88d4-514d-a025-d83b07f28c03', '22222222-2222-2222-2222-222222222204', 'short', '若吴纪或赵嘉参与，则李思参与。', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 7, true, 18, null),
  ('f418c944-01da-5460-8518-0f0809cd1f27', '22222222-2222-2222-2222-222222222204', 'mcq', '若李思或孙斌参与，则周武参与。 现知道周武并未参与该科研攻坚任务，则可以得 出以下哪项?', '[{"key": "A", "text": "李思参与了该科研攻坚任务。"}, {"key": "B", "text": "钱宜参与了该科研攻坚任务。"}, {"key": "C", "text": "吴纪参与了该科研攻坚任务。"}, {"key": "D", "text": "孙斌参与了该科研攻坚任务。"}, {"key": "E", "text": "赵嘉参与了该科研攻坚任务。 母题模型一 事实假言模型 （一）基本型：事实假言模型"}]'::jsonb, '', '', '逻辑/基础必修5-综合推理1.pdf', 7, true, 19, null),
  ('13003219-9a80-53f6-905f-6f078685fc40', '22222222-2222-2222-2222-222222222204', 'short', '吴纪∨赵嘉→李思 假言', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 7, true, 20, null),
  ('6dd15e74-8e41-575b-9246-034e2aa9fbc2', '22222222-2222-2222-2222-222222222204', 'short', '李思∨孙斌→周武 假言', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 7, true, 21, null),
  ('62373686-8084-5135-8511-dbef03d75e90', '22222222-2222-2222-2222-222222222204', 'short', '¬周武 事实 由¬周武可知，¬李思∧¬孙斌 由¬李思可知，¬吴纪∧¬赵嘉 最终只剩钱宜 口诀：题干事实加假言，事实出发做串联； 肯前必肯后，否后必否前。 【例1】', null, 'B', '【第1步 识别命题形式】
题干中，“周武并未参与该科研攻坚任务”为事实，条件(1)和条件(2)均为假言命题，故此题为事实假言
模型。
【第2步 套用母题方法】
从事实出发，由题干可知，周武未参与。
由“周武未参与”可知，条件(2)的后件为假，根据口诀“否后必否前”，可知其前件也为假，即:李思、
孙斌均未参与。
又由“李思未参与”可知，条件(1)的后件为假，根据口诀“否后必否前”，可知其前件也为假，即:吴纪、
赵嘉均未参与。
综上，6人中已有5人被排除，故参与该科研攻坚任务的专家是钱宜，即B项正确。
【例2】
一位编辑正在考虑报纸理论版块稿件的取舍问题。现
有E、F、G、H、J、K六篇论文可供选择。考虑到文章的内
容、报纸的版面等因素，必须满足以下条件:', '逻辑/基础必修5-综合推理1.pdf', 7, true, 22, null),
  ('11b92fd4-7c09-53be-a86a-7ccb353d22f2', '22222222-2222-2222-2222-222222222204', 'short', '如果采用论文E，那么不能采用论文F，但要采用论文K。', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 9, true, 23, null),
  ('8ef77d5e-20d4-543c-b72f-1b69d89295e2', '22222222-2222-2222-2222-222222222204', 'short', '只有不采用论文J，才能采用论文G或论文H。', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 9, true, 24, null),
  ('167fa37c-18a4-5676-bebd-4dde72a88e79', '22222222-2222-2222-2222-222222222204', 'short', '如果不采用论文G，那么也不采用论文K。', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 9, true, 25, null),
  ('39d0725b-768a-5576-91f8-5200918fa4f2', '22222222-2222-2222-2222-222222222204', 'mcq', '论文E是向名人约的稿件，不能不采用。 以上断定如果为真，则下面哪一项也一定是真的?', '[{"key": "A", "text": "采用论文E，但不采用论文H。"}, {"key": "B", "text": "G和H两篇论文都采用。"}, {"key": "C", "text": "不采用论文J，但采用论文K。"}, {"key": "D", "text": "G和J两篇论文都不采用。"}, {"key": "E", "text": "采用论文G，但不采用论文H。 母题模型一 事实假言模型 （一）基本型：事实假言模型"}]'::jsonb, '', '', '逻辑/基础必修5-综合推理1.pdf', 9, true, 26, null),
  ('9bfc9289-678b-546a-8b58-ca899051c7b6', '22222222-2222-2222-2222-222222222204', 'short', 'E→¬F∧K 假言', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 9, true, 27, null),
  ('b99bd707-4bb9-5ea6-bf64-20aebd8bfbc9', '22222222-2222-2222-2222-222222222204', 'short', 'G∨H→¬J 假言', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 9, true, 28, null),
  ('ebc20ebc-05f1-56cc-a495-723d8df18047', '22222222-2222-2222-2222-222222222204', 'short', '¬G→¬K 假言', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 9, true, 29, null),
  ('834f4d3c-aa13-5267-88ea-bd7143eb7b24', '22222222-2222-2222-2222-222222222204', 'short', 'E 事实', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 9, true, 30, null),
  ('98579fd4-db69-5ebd-b976-f737257388a0', '22222222-2222-2222-2222-222222222204', 'short', '+（1）可得：¬F∧K K+（3）可得：G G+（2）可得：¬J 【例2】', null, 'C', '【第1步 识别命题形式】
题干中，条件(4)为事实，条件(1)、(2)和(3)均为假言命题，故此题为事实假言模型。
【第2步 套用母题方法】
从事实出发，由条件（4）可知，采用论文E，即:E。
由“E”可知，条件（1）的前件为真，根据口诀“肯前必肯后”，可知其后件也为真，即:¬F∧K。
由“K”可知，条件（3）的后件为假，根据口诀“否后必否前”，可知其前件也为假，即:G。
由“G”和“选言命题一真则真”可知，条件（2）的前件“G∨H”为真，根据口诀“肯前必肯后”，可
知其后件也为真，即:¬J。
因此，采用论文E、K、G，不采用论文F、J。
母题模型一 事实假言模型
（二）变式1：事实假言+匹配模型
4大核心母题题型（5大条件类）
第一步：
识别命题形式', '逻辑/基础必修5-综合推理1.pdf', 9, true, 31, null),
  ('5c6d9f84-35c5-5a52-a741-c36c15c9164e', '22222222-2222-2222-2222-222222222204', 'short', '题干特点 题干中的已知条件由“事实”“假言命题”和“匹配关系”组成。', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 11, true, 32, null),
  ('24afbe2d-7dfb-598c-b1e5-65d754b57b69', '22222222-2222-2222-2222-222222222204', 'short', '选项特点 题干中的选项多数为事实描述。 第二步： 套用母题方法 解题方法: 步骤1:事实出发做串联。 步骤2:简单匹配做排除，复杂匹配画表格。 【例3】 某公司组织员工乘坐高铁出差，已知如下信息:', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 11, true, 33, null),
  ('f0582ab0-86e1-5933-801b-ce8686c74f45', '22222222-2222-2222-2222-222222222204', 'short', '甲、乙、丙、丁、戊五人乘坐高铁出差，他们正好 坐在同一排的A、B、C、D、F五个座位上。', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 12, true, 34, null),
  ('357ce0eb-9145-5d00-8397-e82e1f91e02f', '22222222-2222-2222-2222-222222222204', 'short', '若甲或者乙中的一人坐在C座，则丙坐在B座。', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 12, true, 35, null),
  ('c2db64fc-53e9-5e43-a04b-713761356a0f', '22222222-2222-2222-2222-222222222204', 'short', '若戊坐在C座，则丁坐在F座。', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 12, true, 36, null),
  ('8a9f95ac-8e80-50a7-a43c-f458b6a5f2c1', '22222222-2222-2222-2222-222222222204', 'mcq', '丁坐在B座。 根据以上信息，可以确定以下哪项?', '[{"key": "A", "text": "甲坐在A座。"}, {"key": "B", "text": "乙坐在D座。"}, {"key": "C", "text": "丙坐在C座。"}, {"key": "D", "text": "戊坐在F座。"}, {"key": "E", "text": "戊坐在A座。 母题模型一 事实假言模型 （二）变式1：事实假言+匹配模型"}]'::jsonb, '', '', '逻辑/基础必修5-综合推理1.pdf', 12, true, 37, null),
  ('e00d9b8a-752c-5ee2-895d-81a0990e0f09', '22222222-2222-2222-2222-222222222204', 'short', '5配5 匹配关系', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 12, true, 38, null),
  ('eddaf8b4-ba07-598c-904b-3721137849ff', '22222222-2222-2222-2222-222222222204', 'short', '甲C∨乙C→丙B 假言', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 12, true, 39, null),
  ('06d51a09-396c-53ca-9080-d7b7ccdd40ab', '22222222-2222-2222-2222-222222222204', 'short', '戊C→丁F 假言', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 12, true, 40, null),
  ('d5109fbf-4cbd-5bf3-928a-b21bf03b1348', '22222222-2222-2222-2222-222222222204', 'short', '丁B 事实', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 12, true, 41, null),
  ('ee5ee0b8-6ab0-5c6b-82b3-4572cbfd6190', '22222222-2222-2222-2222-222222222204', 'short', '+（3）可得：¬戊C', null, '', '', '逻辑/基础必修5-综合推理1.pdf', 12, true, 42, null),
  ('8c8c70fc-6087-5606-a113-4219c2c27725', '22222222-2222-2222-2222-222222222204', 'short', '+（2）可得：¬甲C∧¬乙C 简单匹配做排除 ¬戊C ¬甲C ¬乙C ¬丁C 只能丙C 【例3】', null, 'C', '【第1步 识别命题形式】
题干中，条件(4)为事实，条件(2)、(3)均为假言命题，故本题的主要命题形式为事实假言模型。同时，条件(1)
还涉及“人”与“座位”的匹配关系，故此题为事实假言+匹配模型。
【第2步 套用母题方法】
从事实出发，由条件(4)可知，丁坐在B座。
观察题干信息，发现条件(2)涉及“B座”，条件(3)涉及“丁”。
先看条件(2)，既然丁坐在B座，则丙不可能坐在B座，即条件(2)的后件为假，则其前件也为假，则有:甲和乙
都不坐在C座。
再看条件(3)，既然丁坐在B座，则丁不可能坐在F座，即条件(3)的后件为假，则其前件也为假，则有:戊不坐在
C座。
综上，丁、甲、乙、戊都不坐在C座(简单匹配做排除)，故丙坐在C座。因此，C项正确
