  ('888d5dae-63ec-5f88-9299-1856a9e51362', '22222222-2222-2222-2222-222222222204', 'mcq', '如果选择绿色或者蓝色，那么也会选择紫色。 根据上述信息，以下哪项一定为真?', '[{"key": "A", "text": "老王选择了绿色。"}, {"key": "B", "text": "老王选择了黄色。"}, {"key": "C", "text": "老王选择了青色。"}, {"key": "D", "text": "老王选择了橙色。"}, {"key": "E", "text": "老王选择了红色。 母题模型四 假言推事实模型 （二）变式1：假言推事实+数量模型 7选4，淘汰3种"}]'::jsonb, '', '', '逻辑/基础必修6-综合推理2.pdf', 8, true, 141, null),
  ('dba449fb-6c85-54d0-a0b7-dc5ec2d1978c', '22222222-2222-2222-2222-222222222204', 'short', '¬黄→¬青∧¬紫=青∨紫→黄', null, '', '', '逻辑/基础必修6-综合推理2.pdf', 8, true, 142, null),
