  ('dbc79ba7-dc38-5f44-b3cf-4dec1c034162', '22222222-2222-2222-2222-222222222204', 'short', '若管理学院、经济学院中甲至多应聘1个，则丁应聘管理学院 且乙应聘化学学院。', null, '', '', '逻辑/基础必修6-综合推理2.pdf', 21, true, 179, null),
