  ('e494ad88-4479-501e-97b1-86c90dd4ee05', '22222222-2222-2222-2222-222222222204', 'short', '¬甲管理∨¬甲经济→丁管理∧乙化学', null, '', '', '逻辑/基础必修6-综合推理2.pdf', 21, true, 182, null),
  ('7dcb3dbb-d6be-575b-a4ea-28010f2cea26', '22222222-2222-2222-2222-222222222204', 'short', '乙化学∨丁化学→乙经济∧乙数学', null, '', '', '逻辑/基础必修6-综合推理2.pdf', 21, true, 183, null),
