  ('05b7143b-e5a3-5784-8ab7-56733d4c2156', '22222222-2222-2222-2222-222222222204', 'short', '大熊猫灭绝→西伯利亚虎灭绝。', null, '', '', '逻辑/基础必修6-综合推理2.pdf', 34, true, 219, null),
