  ('49876a44-90c8-5396-8233-0325aca695a7', '22222222-2222-2222-2222-222222222204', 'short', '丙', null, '', '', '逻辑/基础必修7-综合推理3.pdf', 48, true, 309, null),
  ('b480cf2d-d9c0-5494-9e9c-bf4914c156de', '22222222-2222-2222-2222-222222222204', 'short', '甲∧¬乙', null, '', '', '逻辑/基础必修7-综合推理3.pdf', 48, true, 310, null),
  ('bbe520bd-745b-556a-a805-cfc24876af47', '22222222-2222-2222-2222-222222222204', 'short', '甲∨丁', null, '', '', '逻辑/基础必修7-综合推理3.pdf', 48, true, 311, null),
  ('25a30532-932f-574e-914f-4df7d2bdc1c1', '22222222-2222-2222-2222-222222222204', 'short', '和（3）为矛盾命题，故一真一假', null, '', '', '逻辑/基础必修7-综合推理3.pdf', 48, true, 312, null),
  ('38246eb8-9079-5be9-be92-557df95c019f', '22222222-2222-2222-2222-222222222204', 'short', '和（4）均为假', null, '', '', '逻辑/基础必修7-综合推理3.pdf', 48, true, 313, null),
  ('dc12f40e-9457-5e52-9f22-f6f582f47b31', '22222222-2222-2222-2222-222222222204', 'short', '为假可得：¬丙', null, '', '', '逻辑/基础必修7-综合推理3.pdf', 48, true, 314, null),
  ('0a9c82b9-113f-5aef-a488-cdfcbf1d2e93', '22222222-2222-2222-2222-222222222204', 'short', '为假可得：¬甲∧¬丁 最终可得：乙，故一真为（1） 【例10】', null, 'A', '【第1步 识别命题形式】
题干已知“四个断定中只有一个为真”，故此题为真假话问题。
【第2步 套用母题方法】
步骤1:找矛盾。
断定Ⅰ和断定Ⅲ的判断对象一样，故分析这两个断定是否矛盾。
断定Ⅰ:甲→乙。
断定Ⅲ:甲∧¬乙。
由于“A→B”与“A∧B”为矛盾关系，故这两个断定矛盾，必为一真一假。
步骤2:推真假。
根据题干“四个断定中只有一个为真”可知，断定Ⅱ和断定Ⅳ均为假。
步骤3:推出结论。
由断定Ⅱ为假可知，作案者不是丙。
由断定Ⅳ为假可知，作案者不是甲，也不是丁。
由于断定Ⅰ:甲→乙，等价于:¬甲∨乙。
再结合“作案者不是甲”可知，断定Ⅰ为真。
感谢您的聆听
