  ('acfbf971-2d99-542f-8329-69821fd233cf', '22222222-2222-2222-2222-222222222204', 'short', '（半事实假言推事实+匹配模型） 某中学的甲、乙、丙、丁、戊和己6位同学将参加全国 高中生奥赛，每人均参加数学、物理、信息科学技术中的 一种，每种竞赛均有2人参加。还已知:', null, '', '', '逻辑/基础必修8-综合推理4【最终版】.pdf', 32, true, 480, null),
  ('f4b93797-0007-54fe-99fa-51a1a4a8c038', '22222222-2222-2222-2222-222222222204', 'short', '戊和丙中有且仅有1人参加数学竞赛。（半事实）', null, '', '', '逻辑/基础必修8-综合推理4【最终版】.pdf', 32, true, 481, null),
  ('1c92edcd-f76f-5335-b9e9-c0dd5d08939d', '22222222-2222-2222-2222-222222222204', 'short', '如果丁参加物理竞赛，则丙参加数学竞赛。', null, '', '', '逻辑/基础必修8-综合推理4【最终版】.pdf', 32, true, 482, null),
  ('dc6d4a36-7a9c-5f3f-bc21-5192e5e3336d', '22222222-2222-2222-2222-222222222204', 'short', '若乙和丁中至少有1人不参加物理竞赛，那么甲参加物 理竞赛且己参加数学竞赛。', null, '', '', '逻辑/基础必修8-综合推理4【最终版】.pdf', 32, true, 483, null),
  ('8afec0ab-8774-5f40-a2f8-803646cbaa99', '22222222-2222-2222-2222-222222222204', 'mcq', '如果乙不参加信息科学技术竞赛，则戊不参加信息科 学技术竞赛且不参加物理竞赛。 根据上述陈述，可以得出以下哪项?', '[{"key": "A", "text": "戊参加物理竞赛。"}, {"key": "B", "text": "己参加数学竞赛。"}, {"key": "C", "text": "丙参加数学竞赛。"}, {"key": "D", "text": "乙参加信息科学技术竞赛。"}, {"key": "E", "text": "丁不参加信息科学技术竞赛。"}]'::jsonb, '', '', '逻辑/基础必修8-综合推理4【最终版】.pdf', 32, true, 484, null),
  ('5dff993c-c1eb-5ccf-a168-94317f48ab09', '22222222-2222-2222-2222-222222222204', 'short', '有两种情况：①戊数学∧¬丙数学 ②¬戊数学∧丙数学', null, '', '', '逻辑/基础必修8-综合推理4【最终版】.pdf', 32, true, 485, null),
