  ('04d44b9d-57c8-5da7-b062-635134966852', '22222222-2222-2222-2222-222222222204', 'mcq', '对于赵嘉和孙斌来说，如果去了南京，那么也要去 西安。 根据以上信息，可以判断以下各项中一定为真的是: A去西安的是赵嘉和钱宜。', '[{"key": "B", "text": "去拉萨的是钱宜和孙斌。"}, {"key": "C", "text": "孙斌选择去北京、西安和南京。"}, {"key": "D", "text": "赵嘉选择去拉萨、西安和南京。"}, {"key": "E", "text": "钱宜选择去北京、南京和拉萨。 数量关系：总人次为8,每位同事至多能去3个地方，3位 同事人次分配为8=3+3+2"}]'::jsonb, '', '', '逻辑/基础必修8-综合推理4【最终版】.pdf', 34, true, 494, null),
  ('148c845d-fadd-5b45-af8b-f794bf557f29', '22222222-2222-2222-2222-222222222204', 'short', '赵北京→赵南京（2）钱拉萨→钱西安', null, '', '', '逻辑/基础必修8-综合推理4【最终版】.pdf', 34, true, 495, null),
