  ('56140d16-2eb6-58ff-80e7-8cae57b832b7', '22222222-2222-2222-2222-222222222211', 'short', '比：两个数相除，又称为这两个数的比.即𝑎: 𝑏= 𝑎 𝑏其中𝑎叫做比的前 项，𝑏叫做比的后项.相除所得的商叫做比值.记作 𝑎: 𝑏= 𝑎 𝑏= 𝑘.', null, '', '', '数学/第1章 算术2 合订版.pdf', 11, true, 87, null),
  ('66708b27-512d-5a55-be0a-85acdd34492f', '22222222-2222-2222-2222-222222222211', 'short', '比例：相等的比称为比例，记作𝑎: 𝑏= 𝑐: 𝑑或 𝑎 𝑏= 𝑐 𝑑.', null, '', '', '数学/第1章 算术2 合订版.pdf', 11, true, 88, null),
  ('a4f0305a-714e-5060-a51d-f69e7ca88b71', '22222222-2222-2222-2222-222222222211', 'short', '若𝑦= 𝑘𝑥（𝑘≠0）,则称𝑦与𝑥成整比, 𝑘称为比例系数. 本质是𝑦与𝑥的比 值为定值.', null, '', '', '数学/第1章 算术2 合订版.pdf', 11, true, 89, null),
  ('80ad4f4c-85a8-5d66-8e1e-0a43d6875afe', '22222222-2222-2222-2222-222222222211', 'short', '若𝑦= 𝑘 𝑥（𝑘≠0） ,则称𝑦 与𝑥 成反比, 𝑘 称为比例系数. 本质是𝑦 与𝑥的 乘 积为定值.', null, '', '', '数学/第1章 算术2 合订版.pdf', 11, true, 90, null),
  ('2dc36f8d-b216-5882-9e4b-c03a73a69b0f', '22222222-2222-2222-2222-222222222211', 'short', '性质', null, '', '', '数学/第1章 算术2 合订版.pdf', 11, true, 91, null),
  ('33d49ece-974c-52ee-a002-ca8e463e187a', '22222222-2222-2222-2222-222222222211', 'short', '𝑎: 𝑏= 𝑐: 𝑑⇔𝑎𝑑= 𝑏𝑐. 两外项之积等于两内项之积.里里外外.', null, '', '', '数学/第1章 算术2 合订版.pdf', 11, true, 92, null),
  ('10dd3b98-057f-58fb-b9ea-a338bc8e935d', '22222222-2222-2222-2222-222222222211', 'short', '𝑎: 𝑏: 𝑐= 𝑎𝑘: 𝑏𝑘: 𝑐𝑘 (𝑘≠0). 比的各项同乘一个非零常数，比不变.', null, '', '', '数学/第1章 算术2 合订版.pdf', 11, true, 93, null),
  ('8b8d1531-7472-5dea-93d5-fdf0e48c3f94', '22222222-2222-2222-2222-222222222211', 'short', '若𝑥: 𝑦: 𝑧= 𝑎: 𝑏: 𝑐, 则1 𝑥: 1 𝑦: 1 𝑧= 1 𝑎: 1 𝑏: 1 𝑐. 设𝑥= 𝑎𝑘, 𝑦= 𝑏𝑘, 𝑧= 𝑐𝑘(𝑘≠0)， 则1 𝑥: 1 𝑦: 1 𝑧= 1 𝑎𝑘: 1 𝑏𝑘: 1 𝑐𝑘= 1 𝑎𝑘⋅𝑘∶ 1 𝑏𝑘⋅𝑘∶ 1 𝑐𝑘⋅𝑘= 1 𝑎: 1 𝑏: 1 𝑐. 你的坚持，终将美好！ 24', null, '', '', '数学/第1章 算术2 合订版.pdf', 11, true, 94, null),
  ('1f42cd43-7f1c-5562-815a-6c0e4f83459f', '22222222-2222-2222-2222-222222222211', 'short', '定理', null, '', '', '数学/第1章 算术2 合订版.pdf', 12, true, 95, null),
  ('e8b3b7c1-ffa0-5583-8a88-82f82eab3988', '22222222-2222-2222-2222-222222222211', 'short', '合比定理： 𝑎 𝑏= 𝑐 𝑑⇔ 𝑎+𝑏 𝑏= 𝑐+𝑑 𝑑.', null, '', '', '数学/第1章 算术2 合订版.pdf', 12, true, 96, null),
