  ('a8360382-b0a1-5e68-998e-01b034e8df7f', '22222222-2222-2222-2222-222222222211', 'short', '更比定理： 𝑎 𝑏= 𝑐 𝑑⇔ 𝑎 𝑐= 𝑏 𝑑.', null, '', '', '数学/第1章 算术2 合订版.pdf', 12, true, 98, null),
  ('acd933a8-e758-574c-af31-51eaa5438a21', '22222222-2222-2222-2222-222222222211', 'short', '反比定理： 𝑎 𝑏= 𝑐 𝑑⇔ 𝑏 𝑎= 𝑑 𝑐.', null, '', '', '数学/第1章 算术2 合订版.pdf', 12, true, 99, null),
  ('bb26e966-0e03-59e4-aba7-ac2559b4e32f', '22222222-2222-2222-2222-222222222211', 'short', '等比定理： 𝑎 𝑏= 𝑐 𝑑= 𝑒 𝑓= 𝑎+𝑐+𝑒 𝑏+𝑑+𝑓 (𝑏+ 𝑑+ 𝑓≠0). 设 𝑎 𝑏= 𝑐 𝑑= 𝑒 𝑓= 𝑘，则𝑎= 𝑏𝑘, 𝑐= 𝑑𝑘, 𝑒= 𝑓𝑘 那么 𝑎+𝑐+𝑒 𝑏+𝑑+𝑓= 𝑏𝑘+𝑑𝑘+𝑓𝑘 𝑏+𝑑+𝑓 = 𝑘.', null, '', '', '数学/第1章 算术2 合订版.pdf', 12, true, 100, null),
  ('18230b50-eaa3-54bb-8790-4a26bb01d4e1', '22222222-2222-2222-2222-222222222211', 'short', '糖水定理： 𝑎, 𝑏, 𝑘均大于零 ①若0 < 𝑎 𝑏< 1，则 𝑎+𝑘 𝑏+𝑘> 𝑎 𝑏，反之不一定成立. 𝑎+𝑘 𝑏+𝑘− 𝑎 𝑏= 𝑏(𝑎+𝑘)−𝑎(𝑏+𝑘) 𝑏(𝑏+𝑘) = 𝑎𝑏+𝑏𝑘−𝑎𝑏−𝑎𝑘 𝑏(𝑏+𝑘) = 𝑘(𝑏−𝑎) 𝑏(𝑏+𝑘). 0 < 𝑎 𝑏< 1 ⟹𝑎, 𝑏> 0且𝑏> 𝑎，故𝑏−𝑎>0 因此 𝑎+𝑘 𝑏+𝑘− 𝑎 𝑏> 0 ⟹ 𝑎+𝑘 𝑏+𝑘> 𝑎 𝑏 . ②若 𝑎 𝑏> 1，则 𝑎+𝑘 𝑏+𝑘< 𝑎 𝑏，反之不一定成立. ③若 𝑎 𝑏= 1，则 𝑎+𝑘 𝑏+𝑘= 𝑎 𝑏. ④若 𝑏 𝑎< 𝑑 𝑐，并且𝑎,c 同号，则 𝑏 𝑎< 𝑏+𝑑 𝑎+𝑐< 𝑑 𝑐. 【注】证明不等式问题：通常采用作差法和作商法. 你的坚持，终将美好！ 25 题型1：考查比例化简', null, '', '', '数学/第1章 算术2 合订版.pdf', 12, true, 101, null),
  ('9072ac48-a8f2-5efa-8629-d63a54f3e5e8', '22222222-2222-2222-2222-222222222211', 'mcq', '若𝑎: 𝑏= 1 3 : 1 4 ，则12𝑎+ 16𝑏 12𝑎−8𝑏= ( ).', '[{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "−3"}, {"key": "E", "text": "−2"}]'::jsonb, '', '', '数学/第1章 算术2 合订版.pdf', 13, true, 102, null),
  ('ab0ffe06-6f58-5f23-b6e2-9f789f379f23', '22222222-2222-2222-2222-222222222211', 'short', '某公司得到一笔贷款共68 万元，用于下属三个工厂的设备改造，则 甲乙丙三个工厂按比例分别得到36 万元、24 万元和8 万元.', null, '', '', '数学/第1章 算术2 合订版.pdf', 13, true, 103, null),
