  ('9a9c7d0b-c262-55b1-92e1-93e4626f2c4d', '22222222-2222-2222-2222-222222222211', 'short', '非负性：|𝑎| ⩾0，任何实数𝑎的绝对值非负.', null, '', '', '数学/第1章 算术2 合订版.pdf', 19, true, 112, null),
  ('1f407ae2-2567-55c5-a821-0df341dcd626', '22222222-2222-2222-2222-222222222211', 'short', '对称性：|𝑎| = |−𝑎|，即互为相反数的两个数绝对值相等.', null, '', '', '数学/第1章 算术2 合订版.pdf', 19, true, 113, null),
