  ('521ce2c0-c3de-5a7f-a0be-d7ea698daa0d', '22222222-2222-2222-2222-222222222212', 'short', '𝑥+ 𝑦= 1. 你的坚持，终将美好！ 24 你的坚持，终将美好！ 25 考点5：裂项相消法 一、裂项相消 裂项相消法的实质是因式分解的一种形式变换，以若干个分式相加，每个 分式的分子都是1，然后重新组合，使之能消去一些项，最终达到求和的 目的. 二、常考公式 1. 1 𝑛(𝑛+𝑘) = 1 𝑘( 1 𝑛− 1 𝑛+𝑘)，特别地 1 𝑛(𝑛+1) = 1 𝑛− 1 𝑛+1和 1 (𝑛−1)𝑛= 1 𝑛−1 − 1 𝑛. 2. 1 (2𝑛−1)(2𝑛+1) = 1 2 ( 1 2𝑛−1 − 1 2𝑛+1). 3. 1 √𝑛+𝑘−√𝑛= 1 𝑘(√𝑛+ 𝑘+ √𝑛)，特别地 1 √𝑛+1+√𝑛= √𝑛+ 1 −√𝑛.', null, '', '', '数学/第2章 代数式  合订版.pdf', 22, true, 47, null),
  ('196bf1e6-fe58-5415-ab32-1e38e408c0ff', '22222222-2222-2222-2222-222222222213', 'short', '（1）加同为偶，加不同为奇（减法运算与加法一致）；', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 1, true, 1, null),
  ('42b93742-c070-5c66-982b-bfa3bff78e00', '22222222-2222-2222-2222-222222222213', 'short', '乘偶为偶，不乘偶为奇（对任意多组数的情形也成立）.', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 1, true, 2, null),
  ('85e51503-7aad-59f4-833f-6292daa46847', '22222222-2222-2222-2222-222222222213', 'short', '等比定理： 𝑎 𝑏= 𝑐 𝑑= 𝑒 𝑓= 𝑎+𝑐+𝑒 𝑏+𝑑+𝑓 (𝑏+ 𝑑+ 𝑓≠0).', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 1, true, 3, null),
  ('ad4cb9de-a346-568d-9346-06a3419a9f06', '22222222-2222-2222-2222-222222222213', 'short', '𝑎2 + 𝑏2 + 𝑐2 + 𝑎𝑏+ 𝑏𝑐+ 𝑎𝑐= 1 2 [(𝑎+ 𝑏)2 + (𝑏+ 𝑐)2 + (𝑐+ 𝑎)2].', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 1, true, 4, null),
  ('9f669857-bd5c-595b-89dc-2594fc97de92', '22222222-2222-2222-2222-222222222213', 'short', '𝑎3 + 𝑏3 = (𝑎+ 𝑏)(𝑎2 −𝑎𝑏+ 𝑏2)，𝑎3 −𝑏3 = (𝑎−𝑏)(𝑎2 + 𝑎𝑏+ 𝑏2).', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 1, true, 5, null),
  ('dca94555-99a4-5d01-b182-2c7e47fbef83', '22222222-2222-2222-2222-222222222213', 'mcq', '𝑥+ 𝑦+ 𝑧> 0 ⇒𝑥, 𝑦, 𝑧至少有一个大于0； 𝑥+ 𝑦+ 𝑧⩾0 ⇒𝑥, 𝑦, 𝑧至少有一个大于等于0. 6. 1 𝑛(𝑛+𝑘) = 1 𝑘( 1 𝑛− 1 𝑛+𝑘) ， 1 √𝑛+𝑘−√𝑛= 1 𝑘(√𝑛+ 𝑘+ √𝑛). 知新 主讲人：十一老师 现在是网络设备测试时间，课程将准时开始，请大家耐心等待 你的坚持，终将美好！ 16 题型1：考查乘积的裂项 例1： 1 1×2 + 1 2×3 + 1 3×4 + ⋯+ 1 99×100 = ( ).', '[{"key": "A", "text": "99 100"}, {"key": "B", "text": "100 101"}, {"key": "C", "text": "99 101"}, {"key": "D", "text": "97 100"}, {"key": "E", "text": "98 100 题型2：考查根式的裂项 例2： 1 1+√2 + 1 √2+√3 + 1 √3+√4 + ⋯+ 1 √99+√100 = ( )."}, {"key": "A", "text": "9"}, {"key": "B", "text": "10"}, {"key": "C", "text": "11"}, {"key": "D", "text": "3√11 −1"}, {"key": "E", "text": "3√11 你的坚持，终将美好！ 17 你的坚持，终将美好！ 18 题型3：考查分式的裂项"}]'::jsonb, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 1, true, 6, null),
  ('4e4c9b90-525f-5232-afa3-2ec0d0514cc4', '22222222-2222-2222-2222-222222222213', 'mcq', '𝑓(𝑥) = 1 (𝑥+1)(𝑥+2) + 1 (𝑥+2)(𝑥+3) + ⋯+ 1 (𝑥+9)(𝑥+10) , 𝑓(8) = ( ).', '[{"key": "A", "text": "1 9"}, {"key": "B", "text": "1 10"}, {"key": "C", "text": "1 16"}, {"key": "D", "text": "1 17"}, {"key": "E", "text": "1 18 你的坚持，终将美好！ 19 知识咖啡站：（此为自学部分，学有余力的同学自行查看） 一、𝒏次方公式"}]'::jsonb, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 4, true, 7, null),
  ('0e5a878e-c7f6-51f2-a642-871fbc03adcc', '22222222-2222-2222-2222-222222222213', 'short', '𝑥𝑛−1 = (𝑥−1)(𝑥𝑛−1 + 𝑥𝑛−2 + ⋯+ 𝑥+ 1). 证明：等式右边 (𝑥−1)(𝑥𝑛−1 + 𝑥𝑛−2 + ⋯+ 1) = 𝑥(𝑥𝑛−1 + 𝑥𝑛−2 + ⋯+ 1) −(𝑥𝑛−1 + 𝑥𝑛−2 + ⋯+ 1) = 𝑥𝑛+ 𝑥𝑛−1 + 𝑥𝑛−2 + ⋯+ 𝑥2 + 𝑥−(𝑥𝑛−1 + 𝑥𝑛−2 + ⋯+ 𝑥+ 1) = 𝑥𝑛−1 等式右边等于等式左边，因此等式成立. 二、二项展开式 对任意非负整数𝑛，都有 (𝑎+ 𝑏)𝑛= C𝑛 0𝑎𝑛𝑏0 + C𝑛 1𝑎𝑛−1𝑏1 + C𝑛 2𝑎𝑛−2𝑏2 + ⋯C𝑛 𝑛𝑎0𝑏𝑛 其中C𝑛 𝑘= 𝑛! 𝑘!(𝑛−𝑘)! , C𝑛 𝑘= C𝑛 𝑛−𝑘. 例如：(𝑎+ 𝑏)2 = C2 0𝑎2𝑏0 + C2 1𝑎2−1𝑏1 + C2 2𝑎2−2𝑏2 = 𝑎2 + 2𝑎𝑏+ 𝑏2. 三、分解因式 将6𝑥𝑦+ 4𝑥−9𝑦−6分解成两个因式的乘积 思路点拨：这类题从𝑥𝑦项作为突破口，将其分解成含𝑥，𝑦的两项，一般只 考虑整数，即6𝑥𝑦= 𝑥∙6𝑦= 2𝑥∙3𝑦= 3𝑥∙2𝑦= 6𝑥∙𝑦，观察发现4𝑥和9𝑦 分别是2 和3 的倍数，于是我们采用6𝑥𝑦= 2𝑥∙3𝑦这种分解方式. 6𝑥𝑦+ 4𝑥−9𝑦−6 = 2𝑥∙3𝑦+ 2𝑥∙2 −3𝑦∙3 −6 先提出所有𝑥 = 2𝑥(3𝑦+ 2) −3𝑦∙3 −6 想办法凑出3𝑦+ 2 = 2𝑥(3𝑦+ 2) −3(3𝑦+ 2) 合并 = (2𝑥−3)(3𝑦+ 2). 你的坚持，终将美好！ 20 你的坚持，终将美好！ 第三章 集合与函数 考点1 集合 考点2 函数 考点3 一元二次函数 考点4 指数函数 考点5 对数函数 考点6 幂函数 考点7 反比例函数 你的坚持，终将美好！ 1 考点1：集合 一、集合定义 一般地，我们把研究对象统称为元素，把一些元素组成的总体叫做集合.通 常用大写字母𝐴, 𝐵, 𝐶, 𝐷来表示集合，用小写字母𝑎, 𝑏, 𝑐, 𝑑来表示集合的元素。 如集合𝐴= {𝑎, 𝑏, 𝑐}. 二、集合的表示方法', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 5, true, 8, null),
  ('d7ce5bf7-9c27-5bbf-b85c-5c397e5c7fe9', '22222222-2222-2222-2222-222222222213', 'short', '列举法：将集合的元素逐一列举出来方法. 例如：光学的三原色可以用集合{红，绿，蓝}表示.', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 8, true, 9, null),
  ('685ddfe8-6554-583a-937c-b76a391c3e3e', '22222222-2222-2222-2222-222222222213', 'short', '描述法：形式为{代表元素|满足的性质}.（☆☆☆） 例如：由2 的平方根组成的集合𝐴= {𝑥|𝑥2 = 2}.', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 8, true, 10, null),
  ('c141b4fe-1c70-540b-8b34-7b9a9d8582cf', '22222222-2222-2222-2222-222222222213', 'short', 'Venn图 （氏图图）：是一种利用二维平面上的点集表示集合的方法.用平 面上的矩形或圆形表示一个集合，是集合的一种直观的图示表示法. 三、元素、集合的关系', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 8, true, 11, null),
  ('61bbb49f-3efc-5a8a-8fb9-63dc3bb96c1f', '22222222-2222-2222-2222-222222222213', 'short', '元素与集合的关系是属于（符号∈）或不属于（符号∉）表示.', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 8, true, 12, null),
  ('508a7121-aba2-5ffd-ad61-bd5907e7fdf7', '22222222-2222-2222-2222-222222222213', 'short', '集合与集合的关系是包含（符号⊆）与真包含（符号⊂）表示. 你的坚持，终将美好！ 2 四、集合中元素的三要素', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 8, true, 13, null),
  ('cb28b585-fecf-50ad-9c52-f90f575d3a22', '22222222-2222-2222-2222-222222222213', 'short', '确定性：集合中的元素必须是明确的，即对于任何一个对象，都能确定 它是否属于该集合.', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 9, true, 14, null),
  ('97100e6c-755e-534d-8953-e0a27a0e6309', '22222222-2222-2222-2222-222222222213', 'short', '互异性：集合中的元素互不相同，即同一个元素不会重复出现。', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 9, true, 15, null),
  ('6b9dc334-2dbe-5a74-8fc9-a70449afa624', '22222222-2222-2222-2222-222222222213', 'short', '无序性：集合中的元素没有顺序之分,即元素的排列顺序不影响集合本身. 例如：集合{1,2}与集合{2,1}是同一个集合. 五、子集与真子集', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 9, true, 16, null),
  ('62f1ecc9-30bf-51e8-9b66-c7a123bab2af', '22222222-2222-2222-2222-222222222213', 'short', '如果集合𝐴中的每一个元素都是集合𝐵的元素，那么集合𝐴就是集合𝐵的子 集，记作𝐴⊆𝐵，读作“𝐴包含于𝐵”（或“𝐵包含𝐴”）.', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 9, true, 17, null),
  ('a9f9e6da-8625-51ad-ad2b-298836c75f3c', '22222222-2222-2222-2222-222222222213', 'short', '如果集合𝐴是集合𝐵的子集（即𝐴⊆𝐵），但𝐴不等于𝐵 （即𝐴≠𝐵），那么𝐴就 是𝐵的真子集，记作𝐴⊂𝐵，读作“𝐴真包含于𝐵”（或“𝐵真包含𝐴”）.', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 9, true, 18, null),
  ('859432c2-0453-5617-9f10-572946cfcc47', '22222222-2222-2222-2222-222222222213', 'short', '若集合𝐴 是集合𝐵 的子集，集合𝐵 也是集合𝐴 的子集，两两个集合相等,记 为𝐴=𝐵.', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 9, true, 19, null),
  ('0cb1d8fa-9451-5a5b-be7d-edaea8a88397', '22222222-2222-2222-2222-222222222213', 'short', '子集的个数：含有𝑛个元素的集合有2𝑛个子集，2𝑛−1个真子集，2𝑛−1 个非空子集，2𝑛−2个非空真子集. 例如：集合{1,2,3}有子集∅,{1}，{2}，{3}，{1,2}，{1,3}，{2,3}，{1,2,3}. 六、空集 不含任何元素的集合，空集是任何集合的子集，是任何非空集合的真子集， 空集不是无，它是内部没有元素的集合，用符号∅表示. 你的坚持，终将美好！ 3 七、集合的运算', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 9, true, 20, null),
  ('5e3a0c6f-c003-5379-ba29-a9546b288b2b', '22222222-2222-2222-2222-222222222213', 'short', '𝐴∩𝐵：设𝐴, 𝐵是两个集合，由所有既属于集合𝐴又属于集合𝐵的元素组成 的集合叫做集合𝐴与集合𝐵的交集，𝐴∩𝐵= {𝑎∈𝐴且𝑎∈𝐵}.', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 10, true, 21, null),
  ('f73795d0-a612-505f-b2a7-d863a99eac6e', '22222222-2222-2222-2222-222222222213', 'short', '𝐴 𝐵 ：定定两个集合𝐴 ,𝐵 ，把们们所有的元素合并在一组组成的集合叫 做集合𝐴与集合𝐵的并集，𝐴 𝐵={𝑎∈𝐴或𝑎∈𝐵}.', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 10, true, 22, null),
  ('dbb75c66-c8b8-5ee2-ad8d-7c18ed04d62a', '22222222-2222-2222-2222-222222222213', 'short', '𝐴̅：设𝑈是一个集合，𝐴是𝑈的一个子集，由𝑈中所有不属于𝐴的元素组成 的集合叫做𝑈中子集𝐴的补集，𝐴̅ = {𝑥|𝑥∈𝑈且𝑥∉𝐴}. 关系：非此即彼. 题型1：考查集合三要素', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 10, true, 23, null),
  ('287d7e99-6d8c-53c1-b772-409fa50f0ee6', '22222222-2222-2222-2222-222222222213', 'mcq', '已知𝐴= {𝑎+ 2, (𝑎+ 1)2, 𝑎2 + 3𝑎+ 3}，若1 ∈𝐴，求实数𝑎的值( ).', '[{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}, {"key": "E", "text": "0"}]'::jsonb, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 10, true, 24, null),
  ('b63982be-6abc-5091-803c-e86697716773', '22222222-2222-2222-2222-222222222213', 'mcq', '设集合𝐴= {𝑥| |𝑥−𝑎| < 1, 𝑥∈𝐑}，𝐵= {𝑥| |𝑥−𝑏| < 2, 𝑥∈𝐑}，两 𝐴⊂𝐵的充分必要条件是( ).', '[{"key": "A", "text": "|𝑎−𝑏| ⩽1"}, {"key": "B", "text": "|𝑎−𝑏| ⩾1"}, {"key": "C", "text": "|𝑎−𝑏| < 1"}, {"key": "D", "text": "|𝑎−𝑏| > 1"}, {"key": "E", "text": "|𝑎−𝑏| = 1"}]'::jsonb, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 12, true, 25, null),
  ('adbdc9c1-c343-5e1f-a00d-cccf0d736ecc', '22222222-2222-2222-2222-222222222213', 'mcq', '某单位有90 人，其中65 人参加外语培训，72人参加计算机培训，己 知参加外语培训而未参加计算机培训的有8人，两参加计算机培训而 未参加英语培训的人数是( ).', '[{"key": "A", "text": "5"}, {"key": "B", "text": "8"}, {"key": "C", "text": "10"}, {"key": "D", "text": "12"}, {"key": "E", "text": "15"}]'::jsonb, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 12, true, 26, null),
  ('79a69077-500f-56bf-af8c-e8f665987723', '22222222-2222-2222-2222-222222222213', 'short', '一般地，在某一变化过程中有两个变量𝑥与𝑦，如果定定一个𝑥值，相应 地就确定了一个𝑦值，那么称𝑦是𝑥的函数，其中𝑥是自变量，𝑦是因变量.', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 14, true, 27, null),
  ('484b6ce3-3bef-59c4-92e7-0a3abf5ff41b', '22222222-2222-2222-2222-222222222213', 'short', '“元”指方程中所含未知数的个数，“次”指方程中未知数最高的次数. 二、函数的单调性 设函数𝑓(𝑥)的定义域为𝐷，区间𝐼⊆𝐷.', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 14, true, 28, null),
  ('5618f364-3e4c-5098-a801-a894635421d1', '22222222-2222-2222-2222-222222222213', 'short', '对任意𝑥1, 𝑥2 ∈𝐼，当𝑥1 < 𝑥2时，都有𝑓(𝑥1) < 𝑓(𝑥2)，那么就称函数𝑓(𝑥) 在区间𝐼上单调递增. 特别地，当函数𝑓(𝑥)在它的定义域上单调递增时，称它为增函数.', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 14, true, 29, null),
  ('d8175419-5b8d-5a19-af70-921d07b00737', '22222222-2222-2222-2222-222222222213', 'short', '对任意𝑥1, 𝑥2 ∈𝐼，当𝑥1 < 𝑥2时，都有𝑓(𝑥1) > 𝑓(𝑥2)，那么就称函数𝑓(𝑥) 在区间𝐼上单调递减. 特别地，当函数𝑓(𝑥)在它的定义域上单调递减时，称它为减函数. 你的坚持，终将美好！ 8 三、函数的奇偶性', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 14, true, 30, null),
  ('5e0e6028-dce6-5c67-9a6b-b6580ff0765b', '22222222-2222-2222-2222-222222222213', 'short', '偶函数：一般地，设函数𝑓(𝑥)的定义域为𝐷，如果对任意𝑥∈𝐷，都有 −𝑥∈𝐷，且𝑓(𝑥) = 𝑓(−𝑥)，那么函数𝑓(𝑥)叫做偶函数. 例如：𝑓(𝑥) = 𝑥2 + 1，𝑔(𝑥) = 2 𝑥2+1都是偶函数.', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 15, true, 31, null),
  ('4b198209-46f3-5b36-8c7a-0b5eef4b3b62', '22222222-2222-2222-2222-222222222213', 'short', '奇函数：一般地，设函数𝑓(𝑥)的定义域为𝐷，如果对任意𝑥∈𝐷，都有 −𝑥∈𝐷，且𝑓(𝑥) = −𝑓(−𝑥)，那么函数𝑓(𝑥)叫做奇函数. 例如：𝑓(𝑥) = 𝑥，𝑔(𝑥) = 1 𝑥都是奇函数. 小试牛刀', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 15, true, 32, null),
  ('34e09d29-48a3-535d-a789-1037d5ec3e9f', '22222222-2222-2222-2222-222222222213', 'mcq', '已知𝑓(𝑥)为定义在𝐑上的奇函数，当𝑥⩾0时，𝑓(𝑥) = 2𝑥+ 2𝑥−1，两 𝑓(−1) = ( ).', '[{"key": "A", "text": "−3"}, {"key": "B", "text": "−1"}, {"key": "C", "text": "1"}, {"key": "D", "text": "3"}, {"key": "E", "text": "4"}]'::jsonb, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 15, true, 33, null),
  ('0c89fbdb-6f4f-547a-8179-5bfb1fff3769', '22222222-2222-2222-2222-222222222213', 'mcq', '下列函数中，是正比例函数的是( ).', '[{"key": "A", "text": "𝑦= 1 2 𝑥"}, {"key": "B", "text": "𝑦= 4 𝑥"}, {"key": "C", "text": "𝑦= 5𝑥−3"}, {"key": "D", "text": "𝑦= 6𝑥2 −2𝑥−1"}, {"key": "E", "text": "𝑦= 4𝑥+ 3 例2、一次函数𝑦= 𝑘𝑥−𝑘，若𝑦随着𝑥的增大而减小，两该函数图像过( )."}, {"key": "A", "text": "一、二、三象限"}, {"key": "B", "text": "一、二、四象限"}, {"key": "C", "text": "一、三、四象限"}, {"key": "D", "text": "二、三、四象限"}, {"key": "E", "text": "以上答案均不对"}]'::jsonb, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 17, true, 34, null),
  ('5f707328-055a-5853-8bdd-6a811cd2a58c', '22222222-2222-2222-2222-222222222213', 'mcq', '直线𝑦= 𝑘𝑥+ 1一定过点( ).', '[{"key": "A", "text": "(1,0)"}, {"key": "B", "text": "(1, 𝑘)"}, {"key": "C", "text": "(0. 𝑘)"}, {"key": "D", "text": "(0,1)"}, {"key": "E", "text": "(𝑘, 0) 提示：𝒌是可变的，过定点需要消除𝒌的影响."}]'::jsonb, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 17, true, 35, null),
  ('1613e8a6-e835-5c81-8137-0e74da5ccc93', '22222222-2222-2222-2222-222222222213', 'short', '表达式：', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 18, true, 36, null),
  ('1bf39c1f-8670-564c-8d8c-0e56e23a4c33', '22222222-2222-2222-2222-222222222213', 'short', '一般式：𝑦= 𝑎𝑥2 + 𝑏𝑥+ 𝑐，(𝑎≠0，𝑎、𝑏、𝑐均为常数).', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 18, true, 37, null),
  ('00a69e0c-8030-5780-83c9-ad63bb6c6345', '22222222-2222-2222-2222-222222222213', 'short', '交点式：𝑦= 𝑎(𝑥−𝑥1)(𝑥−𝑥2). 𝑥1、𝑥2是函数图像与𝑥轴的交点横坐标，也叫函数的零点，也是一元二 次方程的两个根.', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 18, true, 38, null),
  ('9dd68811-0587-5df9-97ae-b10d6a8a9c84', '22222222-2222-2222-2222-222222222213', 'short', '顶点式：𝑦= 𝑎(𝑥+ 𝑏 2𝑎) 2 + 4𝑎𝑐−𝑏2 4𝑎 . 对称轴𝑥= − 𝑏 2𝑎，顶点坐标(− 𝑏 2𝑎, 4𝑎𝑐−𝑏2 4𝑎 )（☆），最值在顶点处取得. 推导：𝑦= 𝑎𝑥2 + 𝑏𝑥+ 𝑐 =𝑎(𝑥2 + 𝑏 𝑎𝑥) + 𝑐 = 𝑎[𝑥2 + 2𝑥⋅𝑏 2𝑎+ ( 𝑏 2𝑎) 2 ] −𝑎⋅( 𝑏 2𝑎) 2 + 𝑐 = 𝑎(𝑥+ 𝑏 2𝑎) 2 + 4𝑎𝑐−𝑏2 4𝑎 .', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 18, true, 39, null),
  ('22f966d5-7dac-5ce0-ad7d-1a936b0b3047', '22222222-2222-2222-2222-222222222213', 'short', '性质：', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 18, true, 40, null),
  ('07a366df-f53d-5dde-94eb-7d69e4ebecab', '22222222-2222-2222-2222-222222222213', 'short', '𝑎的影响（决定抛物线开口方向） 当𝑎> 0，抛物线开口向上；当𝑎< 0，抛物线开口向下. 【注】当𝒂> 𝟎，函数有最小值 𝟒𝒂𝒄−𝒃𝟐 𝟒𝒂 ；当𝒂< 𝟎，函数有最大值 𝟒𝒂𝒄−𝒃𝟐 𝟒𝒂 . 你的坚持，终将美好！ 12', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 18, true, 41, null),
  ('26794491-babe-55fc-be09-204b8a6e6736', '22222222-2222-2222-2222-222222222213', 'short', '𝑎、𝑏的影响 当对称轴𝑥= − 𝑏 2𝑎> 0，对称轴在𝑦轴的右侧. 当对称轴𝑥= − 𝑏 2𝑎= 0，对称轴就是𝑦轴. 当对称轴𝑥= − 𝑏 2𝑎< 0，对称轴在𝑦轴的左侧.', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 19, true, 42, null),
  ('c6b50208-a7a8-5dd2-936d-77692d465068', '22222222-2222-2222-2222-222222222213', 'short', '𝑐的影响，（𝑥= 0，解得𝑦= 𝑐，𝑐决定了抛物线与𝑦轴交点的位置） 抛物线与𝑦轴的交点为(0, 𝑐)，表示抛物线在𝑦轴的截距. 当𝑐> 0时，抛物线与𝑦轴的交点在𝑦轴正方向. 当𝑐= 0时，抛物线与𝑦轴的交点在原点(0,0). 当𝑐< 0时，抛物线与𝑦轴的交点在𝑦轴负方向. 【注】截距可正、可负、可为0.', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 19, true, 43, null),
  ('eff5ce03-b5a7-5009-910c-fb7105ffe3d5', '22222222-2222-2222-2222-222222222213', 'short', '根的判别式∆= 𝑏2 −4𝑎𝑐（☆），决定抛物线与𝑥轴的交点个数. 当∆> 0时，有两个交点. 当∆= 0时，有一个交点，此时顶点在𝑥轴上. 当∆< 0时，无交点. 在有实根的情况下𝑥1 = −𝑏+√∆ 2𝑎，𝑥2 = −𝑏−√∆ 2𝑎. 【注】两个交点的距离|𝒙𝟏−𝒙𝟐| = √∆ |𝒂|. 你的坚持，终将美好！ 13', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 19, true, 44, null),
  ('de00a46e-4a54-5ae5-88a8-3d821f00eda9', '22222222-2222-2222-2222-222222222213', 'short', '若𝑎+ 𝑏+ 𝑐= 0，抛物线过点(1,0). 若𝑎−𝑏+ 𝑐= 0，抛物线过点(−1,0).', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 20, true, 45, null),
  ('0989fbd3-9fd0-5332-83cd-a86b0958efc9', '22222222-2222-2222-2222-222222222213', 'short', '一元二次函数图像 你的坚持，终将美好！ 14 题型1：考查参数值的求解', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 20, true, 46, null),
  ('e088366c-6f27-5be8-995b-e9225469da71', '22222222-2222-2222-2222-222222222213', 'mcq', '已知二次函数𝑦= 𝑎𝑥2 + 𝑏𝑥+ 𝑐的图像如图所示，两𝑎, 𝑏, 𝑐满足( ).', '[{"key": "A", "text": "𝑎< 0, 𝑏< 0, 𝑐> 0"}, {"key": "B", "text": "𝑎< 0, 𝑏< 0, 𝑐< 0"}, {"key": "C", "text": "𝑎< 0, 𝑏> 0, 𝑐> 0"}, {"key": "D", "text": "𝑎> 0, 𝑏< 0, 𝑐> 0"}, {"key": "E", "text": "𝑎> 0, 𝑏< 0, 𝑐> 0"}]'::jsonb, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 21, true, 47, null),
  ('1e2bc64a-05b9-5b10-8b57-2dca5b9d9345', '22222222-2222-2222-2222-222222222213', 'mcq', '已知二次函数𝑦= 𝑎𝑥2 + 𝑏𝑥+ 𝑐的图像顶点坐标为(2, −1)，与𝑦轴的 交点为(0,11)，两有( ).', '[{"key": "A", "text": "𝑎= 1, 𝑏= −4, 𝑐= 11"}, {"key": "B", "text": "𝑎= 3, 𝑏= 12, 𝑐= 11"}, {"key": "C", "text": "𝑎= 1, 𝑏= 4, 𝑐= 11"}, {"key": "D", "text": "𝑎= 3, 𝑏= −12, 𝑐= 11"}, {"key": "E", "text": "𝑎= 1, 𝑏= −12, 𝑐= 11"}]'::jsonb, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 21, true, 48, null),
  ('936c12b5-cf61-5343-9879-be39e220cfe4', '22222222-2222-2222-2222-222222222213', 'mcq', '设二次函数𝑓(𝑥) = 𝑎𝑥2 + 𝑏𝑥+ 𝑐，且𝑓(2) = 𝑓(0)，且 𝑓(3)−𝑓(2) 𝑓(2)−𝑓(1)=( ).', '[{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}, {"key": "E", "text": "6"}]'::jsonb, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 23, true, 49, null),
  ('c5da7612-211b-5288-9a05-be7186dcfe37', '22222222-2222-2222-2222-222222222213', 'mcq', '如果函数𝑓(𝑥) = 𝑥2 + 2(𝑎−1)𝑥+ 2在区间(−∞, 4]上递减的，那么实 数𝑎的取值范围为( ).', '[{"key": "A", "text": "𝑎⩽−3"}, {"key": "B", "text": "𝑎⩾−3"}, {"key": "C", "text": "𝑎⩽5"}, {"key": "D", "text": "𝑎⩾5"}, {"key": "E", "text": "以上均不正确"}]'::jsonb, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 23, true, 50, null),
  ('e0cbb0fe-494e-5bb5-9b01-4dae9a06bea9', '22222222-2222-2222-2222-222222222213', 'short', '（2） 你的坚持，终将美好！ 18 题型4：考查函数的最值', null, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 24, true, 51, null),
  ('8c518ae3-5efb-5058-b733-fc1ac0873aef', '22222222-2222-2222-2222-222222222213', 'mcq', '函数𝑓(𝑥) = max {𝑥2, −𝑥2 + 8}的最小值为( ).', '[{"key": "A", "text": "8"}, {"key": "B", "text": "7"}, {"key": "C", "text": "6"}, {"key": "D", "text": "5"}, {"key": "E", "text": "4"}]'::jsonb, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 25, true, 52, null),
