  ('bf571d53-3915-53fd-96cb-4c8d013dc61d', '22222222-2222-2222-2222-222222222213', 'short', '集合元素的互异性：集合中的元素互不相同，即同一个元素不会重复出现.', null, '', '', '数学/第3章 集合与函数（2）含解析的合订版.pdf', 1, true, 54, null),
  ('b60db6cd-16ff-51d8-92f3-98a64dcddfae', '22222222-2222-2222-2222-222222222213', 'short', '含有𝑛个元素的集合有2𝑛个子集.', null, '', '', '数学/第3章 集合与函数（2）含解析的合订版.pdf', 1, true, 55, null),
  ('34275d33-7afa-519f-840e-c086f41f8967', '22222222-2222-2222-2222-222222222213', 'short', '（1）满足定义域时，𝑓(𝑥) = 𝑓(−𝑥)，函数𝑓(𝑥)叫做偶函数.', null, '', '', '数学/第3章 集合与函数（2）含解析的合订版.pdf', 1, true, 56, null),
  ('f9990b46-d45a-5d4a-a3b5-0b30d53f2e75', '22222222-2222-2222-2222-222222222213', 'short', '满足定义域时，𝑓(𝑥) = −𝑓(−𝑥)，函数𝑓(𝑥)叫做奇函数， 特别地，当𝑥可以取0 时，奇函数一定有𝑓(0) = 0.', null, '', '', '数学/第3章 集合与函数（2）含解析的合订版.pdf', 1, true, 57, null),
  ('1766b5c9-f16c-5377-ac28-19b5b2963ebf', '22222222-2222-2222-2222-222222222213', 'short', '一元二次函数𝑦= 𝑎𝑥2 + 𝑏𝑥+ 𝑐，对称轴𝑥= − 𝑏 2𝑎，顶点坐标(− 𝑏 2𝑎, 4𝑎𝑐−𝑏2 4𝑎 ).', null, '', '', '数学/第3章 集合与函数（2）含解析的合订版.pdf', 1, true, 58, null),
  ('c12c6168-5a4b-5c1c-927b-12182228b872', '22222222-2222-2222-2222-222222222213', 'short', '根的判别式∆= 𝑏2 −4𝑎𝑐. 有实根时 𝑥1 = −𝑏+√∆ 2𝑎，𝑥2 = −𝑏−√∆ 2𝑎. 知新 主讲人：十一老师 现在是网络设备测试时间，课程将准时开始，请大家耐心等待 你的坚持，终将美好！ 15 题型4：考查函数的对称性', null, '', '', '数学/第3章 集合与函数（2）含解析的合订版.pdf', 1, true, 59, null),
  ('2c4ab2b2-032d-5fa9-969f-876867a641f7', '22222222-2222-2222-2222-222222222213', 'mcq', '如果函数𝑓(𝑥) = 𝑥2 + 𝑏𝑥+ 𝑐,对于任意实数𝑡都有𝑓(3 + 𝑡) = 𝑓(3 −𝑡), 那么( ).', '[{"key": "A", "text": "𝑓(3) < 𝑓(1) < 𝑓(4)"}, {"key": "B", "text": "𝑓(1) < 𝑓(3) < 𝑓(4) C. 𝑓(3) < 𝑓(4) < 𝑓(1)"}, {"key": "D", "text": "𝑓(4) < 𝑓(3) < 𝑓(1) E. 𝑓(4) < 𝑓(1) < 𝑓(3) 提示：若函数𝑓(𝑥)关于直线𝒙= 𝒂对称， 则有𝒇(𝒂+ 𝒙) = 𝒇(𝒂−𝒙) ⇔ 𝒇(𝒙) = 𝒇(𝟐𝒂−𝒙)."}]'::jsonb, '', '', '数学/第3章 集合与函数（2）含解析的合订版.pdf', 2, true, 60, null),
  ('b5aa352c-a01b-57dd-86e7-eb9e958ed885', '22222222-2222-2222-2222-222222222213', 'short', '相关概念', null, '', '', '数学/第3章 集合与函数（2）含解析的合订版.pdf', 4, true, 61, null),
  ('47497291-51d6-53a3-a13f-b42f8fa5b144', '22222222-2222-2222-2222-222222222213', 'short', '𝑦= 𝑎𝑥(𝑎> 0, 𝑎≠1)，其定义域为(−∞, +∞)，值域为(0, +∞).', null, '', '', '数学/第3章 集合与函数（2）含解析的合订版.pdf', 4, true, 62, null),
  ('65445850-35be-51d8-95fa-712a97ee7722', '22222222-2222-2222-2222-222222222213', 'short', '0 < 𝑎< 1时，函数严格单调递减；𝑎> 1时，函数严格单调递增.', null, '', '', '数学/第3章 集合与函数（2）含解析的合订版.pdf', 4, true, 63, null),
