  ('eefb1299-e2fe-5de9-b88e-27da8a5bdf09', '22222222-2222-2222-2222-222222222213', 'short', '一元二次方程：𝑎𝑥2 + 𝑏𝑥+ 𝑐= 0 (𝑎≠0). 二、一元二次方程根的判别式 ∆= 𝑏2 −4𝑎𝑐', null, '', '', '数学/第3章 集合与函数（2）含解析的合订版.pdf', 22, true, 107, null),
  ('8988b89b-63ec-583b-9bd2-f4d80f2457ac', '22222222-2222-2222-2222-222222222213', 'short', '当∆> 0时，方程有两个不相等的实根，根为𝑥1 = −𝑏+√∆ 2𝑎，𝑥2 = −𝑏−√∆ 2𝑎.', null, '', '', '数学/第3章 集合与函数（2）含解析的合订版.pdf', 22, true, 108, null),
  ('37d6de52-25d6-599b-8cd9-b5a976754d92', '22222222-2222-2222-2222-222222222213', 'short', '当∆= 0时，方程有两个相等的实根，𝑥1 = 𝑥2 = − 𝑏 2𝑎.', null, '', '', '数学/第3章 集合与函数（2）含解析的合订版.pdf', 22, true, 109, null),
  ('76964d0f-0f20-5c77-9cc1-bab277f57b4f', '22222222-2222-2222-2222-222222222213', 'short', '当∆< 0时，方程无实根. 你的坚持，终将美好！ 5 三、几个等价表述', null, '', '', '数学/第3章 集合与函数（2）含解析的合订版.pdf', 22, true, 110, null),
  ('6203a033-5017-5095-9a17-024f154ed301', '22222222-2222-2222-2222-222222222213', 'short', '∆= 0 ⇔一元二次方程有两个相等的实根. ⇔一元二次函数与𝑥轴有且仅有一个交点. ⇔一元二次函数是一个完全平方式. ⇔一元二次函数的最大值（最小值）为0. ⇔一元二次函数与𝑥轴相切. ⇔一元二次函数只有一个零点. ⇔一元二次函数与一元一次函数只有一个交点. 例如： 𝑦= 𝑎𝑥2 + 𝑏𝑥+ 𝑐与𝑦= 𝑘𝑥+ 𝑚联立， 得 𝑎𝑥2 + 𝑏𝑥+ 𝑐= 𝑘𝑥+ 𝑚 ⇒𝑎𝑥2 + (𝑏−𝑘)𝑥+ (𝑐−𝑚) = 0 此时问题就转化成：一元二次方程有两个相等的实根.', null, '', '', '数学/第3章 集合与函数（2）含解析的合订版.pdf', 23, true, 111, null),
  ('65c08ff2-0c0d-5d47-a571-b9cf03f33c80', '22222222-2222-2222-2222-222222222213', 'short', '∆> 0 ⇔一元二次方程有两个不相等的实根. ⇔一元二次函数与𝑥轴有两个交点. ⇔一元二次函数与𝑥轴相交. ⇔一元二次函数有两个零点. ⇔一元二次函数与一元一次函数有两个交点.', null, '', '', '数学/第3章 集合与函数（2）含解析的合订版.pdf', 23, true, 112, null),
  ('09d0ebf3-8616-52cc-bf85-16686dc8ed50', '22222222-2222-2222-2222-222222222213', 'short', '∆< 0 ⇔一元二次方程没有实根. ⇔一元二次函数与𝑥轴没有交点. ⇔一元二次函数与𝑥轴相离. ⇔一元二次函数没有零点. ⇔一元二次函数与一元一次函数没有交点.', null, '', '', '数学/第3章 集合与函数（2）含解析的合订版.pdf', 23, true, 113, null),
  ('5d47020b-e234-5ce4-818d-e27c46477e59', '22222222-2222-2222-2222-222222222214', 'short', '𝑎3 + 𝑏3 = (𝑎+ 𝑏)(𝑎2 −𝑎𝑏+ 𝑏2).', null, '', '', '数学/第4章 方程与不等式（1） 含解析的合订版.pdf', 1, true, 1, null),
  ('63a41614-a4db-5832-be0b-9d856dd92bd8', '22222222-2222-2222-2222-222222222214', 'short', '𝑓(𝑥)含有(𝑥−𝑎)的因式⇔𝑓(𝑥)能被(𝑥−𝑎)整除⇔𝑓(𝑎) = 0.', null, '', '', '数学/第4章 方程与不等式（1） 含解析的合订版.pdf', 1, true, 2, null),
  ('0c44d404-fbb1-5be6-a9eb-8bf06d2189f8', '22222222-2222-2222-2222-222222222214', 'short', '一元二次函数𝑦= 𝑎𝑥2 + 𝑏𝑥+ 𝑐，对称轴𝑥= − 𝑏 2𝑎，顶点坐标(− 𝑏 2𝑎, 4𝑎𝑐−𝑏2 4𝑎 ).', null, '', '', '数学/第4章 方程与不等式（1） 含解析的合订版.pdf', 1, true, 3, null),
  ('15ce18ea-fc95-5004-9a32-a5fcc64ddac3', '22222222-2222-2222-2222-222222222214', 'short', '根的判别式∆= 𝑏2 −4𝑎𝑐. 有实根时 𝑥1 = −𝑏+√∆ 2𝑎，𝑥2 = −𝑏−√∆ 2𝑎.', null, '', '', '数学/第4章 方程与不等式（1） 含解析的合订版.pdf', 1, true, 4, null),
  ('1a44a2b7-3d6d-50b7-9255-5f8efa7a530a', '22222222-2222-2222-2222-222222222214', 'short', '若函数𝑓(𝑥)关于直线𝑥= 𝑎对称,则𝑓(𝑎+ 𝑥) = 𝑓(𝑎−𝑥) ⇔𝑓(𝑥) = (2𝑎−𝑥). 6.', null, '', '', '数学/第4章 方程与不等式（1） 含解析的合订版.pdf', 1, true, 5, null),
  ('7c2cb593-fe08-54ce-bbc7-266da48c58b2', '22222222-2222-2222-2222-222222222214', 'mcq', '换底公式：log𝑎𝑏= log𝑐𝑏 log𝑐𝑎. 知新 主讲人：十一老师 现在是网络设备测试时间，课程将准时开始，请大家耐心等待 你的坚持，终将美好！ 5 题型1：考查根的判别式 要求判断每题给出的条件（1）和（2）能否充分支持题干所陈述的结论．以下五个选项为判 断结果，请选择一项符合试题要求的判断。', '[{"key": "A", "text": "条件（1）充分，但条件（2）不充分"}, {"key": "B", "text": "条件（2）充分，但条件（1）不充分"}, {"key": "C", "text": "条件（1）和（2）单独都不充分，但条件（1）和条件（2）联合起来充分"}, {"key": "D", "text": "条件（1）充分，条件（2）也充分"}, {"key": "E", "text": "条件（1）和条件（2）单独都不充分，条件（1）和条件（2）联合起来也不充分"}]'::jsonb, '', '', '数学/第4章 方程与不等式（1） 含解析的合订版.pdf', 1, true, 6, null),
