  ('a2bfc946-95e7-5d96-8dc7-eded722f6fae', '22222222-2222-2222-2222-222222222214', 'mcq', '已知方程3𝑥2 + 𝑚𝑥+ 5 = 0的两根为𝑥1, 𝑥2，满足 1 𝑥1 + 1 𝑥2 = 1，则𝑚的 值等于( ).', '[{"key": "A", "text": "5"}, {"key": "B", "text": "−5"}, {"key": "C", "text": "3"}, {"key": "D", "text": "−3"}, {"key": "E", "text": "以上选项均不正确"}]'::jsonb, '', '', '数学/第4章 方程与不等式（1） 含解析的合订版.pdf', 9, true, 25, null),
  ('b4eea333-fcec-53ed-bd3d-7e19a814a255', '22222222-2222-2222-2222-222222222214', 'mcq', '已知𝑥1, 𝑥2是方程𝑥2 −𝑎𝑥−1 = 0的两个实根，则𝑥1 2 + 𝑥2 2 = ( ).', '[{"key": "A", "text": "𝑎2 + 2"}, {"key": "B", "text": "𝑎2 + 1"}, {"key": "C", "text": "𝑎2 −1"}, {"key": "D", "text": "𝑎2 −2"}, {"key": "E", "text": "𝑎2"}]'::jsonb, '', '', '数学/第4章 方程与不等式（1） 含解析的合订版.pdf', 9, true, 26, null),
  ('614a4803-a05d-525d-9603-123494e9db63', '22222222-2222-2222-2222-222222222214', 'mcq', '若𝑛(𝑛≠0)是关于𝑥的方程𝑥2 + 2𝑚𝑥+ 3𝑛= 0的根，则2𝑚+ 𝑛的值是 ( ).', '[{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "−1"}, {"key": "D", "text": "−3"}, {"key": "E", "text": "0"}]'::jsonb, '', '', '数学/第4章 方程与不等式（1） 含解析的合订版.pdf', 11, true, 27, null),
  ('da778ea3-215d-5532-aca2-59c74491d767', '22222222-2222-2222-2222-222222222214', 'mcq', '关于𝑥的一元二次方程𝑥2 −𝑚𝑥+ 2𝑚−1 = 0的两个实根分别是𝑥1, 𝑥2, (𝑥1 ≠𝑥2)且𝑥1 2 + 𝑥2 2 = 7，则(𝑥1 −𝑥2)2的值是( ).', '[{"key": "A", "text": "11"}, {"key": "B", "text": "15"}, {"key": "C", "text": "13"}, {"key": "D", "text": "17"}, {"key": "E", "text": "19"}]'::jsonb, '', '', '数学/第4章 方程与不等式（1） 含解析的合订版.pdf', 11, true, 28, null),
  ('84e5bdc5-1d75-597d-a80f-44f0bc0ca7f6', '22222222-2222-2222-2222-222222222214', 'mcq', '若方程𝑥2 + 𝑝𝑥+ 37 = 0恰有两个正整数解𝑥1和𝑥2，则 (𝑥1+1)(𝑥2+1) 𝑝 的值 是( ).', '[{"key": "A", "text": "−2"}, {"key": "B", "text": "−1"}, {"key": "C", "text": "−1"}]'::jsonb, '', '', '数学/第4章 方程与不等式（1） 含解析的合订版.pdf', 13, true, 29, null),
  ('7375eae3-b832-5b0e-a1d6-47d9c7d3cd79', '22222222-2222-2222-2222-222222222214', 'mcq', '若方程𝑥2 + 𝑝𝑥+ 1 = 0(𝑝> 0)的两根之差是1，那么𝑝的值是( ).', '[{"key": "A", "text": "2"}, {"key": "B", "text": "−√5"}, {"key": "C", "text": "−1"}, {"key": "D", "text": "√5"}, {"key": "E", "text": "√3"}]'::jsonb, '', '', '数学/第4章 方程与不等式（1） 含解析的合订版.pdf', 13, true, 30, null),
  ('6639e08a-3fe6-542b-859c-6afa5790d82c', '22222222-2222-2222-2222-222222222214', 'short', '一元二次方程𝑎𝑥2 + 𝑏𝑥+ 𝑐= 0(𝑎≠0)有两个正根， 则 { ∆⩾0 𝑥1 + 𝑥2 = − 𝑏 𝑎> 0 𝑥1𝑥2 = 𝑐 𝑎> 0 ⇔ ∆⩾0，𝑎𝑏< 0，𝑎𝑐> 0.', null, '', '', '数学/第4章 方程与不等式（1） 含解析的合订版.pdf', 15, true, 31, null),
  ('a4077091-f676-5e90-a1d2-8c3231b9541b', '22222222-2222-2222-2222-222222222214', 'short', '一元二次方程𝑎𝑥2 + 𝑏𝑥+ 𝑐= 0(𝑎≠0)有两个负根， 则 { ∆⩾0 𝑥1 + 𝑥2 = − 𝑏 𝑎< 0 𝑥1𝑥2 = 𝑐 𝑎> 0 ⇔ ∆⩾0，𝑎, 𝑏, 𝑐同号.', null, '', '', '数学/第4章 方程与不等式（1） 含解析的合订版.pdf', 15, true, 32, null),
  ('163052e1-7b4e-59a5-9f47-1a557a983d29', '22222222-2222-2222-2222-222222222214', 'short', '一元二次方程𝑎𝑥2 + 𝑏𝑥+ 𝑐= 0(𝑎≠0)有一正一负两个根， 则 { ∆> 0 𝑥1𝑥2 = 𝑐 𝑎< 0 ⇔ ∆> 0，𝑎, 𝑐异号. 二、根的存在定理', null, '', '', '数学/第4章 方程与不等式（1） 含解析的合订版.pdf', 15, true, 33, null),
  ('6cfc01f9-8785-56ae-9501-945cb8a07adf', '22222222-2222-2222-2222-222222222214', 'short', '一元二次方程𝑎𝑥2 + 𝑏𝑥+ 𝑐= 0(𝑎≠0)的根就是二次函数𝑓(𝑥) = 𝑎𝑥2 + 𝑏𝑥+ 𝑐的图像与𝑥轴交点的横坐标.', null, '', '', '数学/第4章 方程与不等式（1） 含解析的合订版.pdf', 15, true, 34, null),
  ('a7b138f5-e092-515b-a56b-2be9b1859257', '22222222-2222-2222-2222-222222222214', 'short', '对于函数𝑦= 𝑓(𝑥)，我们把使𝑓(𝑥) = 0的𝑥值叫做函数的零点. 你的坚持，终将美好！ 19', null, '', '', '数学/第4章 方程与不等式（1） 含解析的合订版.pdf', 15, true, 35, null),
