  ('d65b9107-4a97-54f7-ba18-aa700d15d732', '22222222-2222-2222-2222-222222222214', 'short', '对任意实数𝑎, 𝑏，有𝑎2 + 𝑏2 ⩾2𝑎𝑏. 当且仅当𝑎= 𝑏时，等号成立.', null, '', '', '数学/第4章 方程与不等式（3） 含解析的合订版（适合使用在线文档查看的同学）.pdf', 12, true, 83, null),
