  ('f9bea983-4a88-5857-8fa6-60e9ab7da768', '22222222-2222-2222-2222-222222222215', 'short', '𝑛. 𝑑≠0时，等差数列的前𝑛项和是一个关于𝑛的没有常数项的二次函数. 还有如下等价条件：前𝑛项和𝑆𝑛= 𝐴𝑛2 + 𝐵𝑛 ⇔ 数列{𝑎𝑛}是等差数列. 证明：𝑆𝑛= 𝐴𝑛2 + 𝐵𝑛 ⇒ 𝑎𝑛是等差数列', null, '', '', '数学/第5章 数列（1）.pdf', 9, true, 73, null),
  ('c38e3e16-812b-5959-bf47-ff6a4755d20c', '22222222-2222-2222-2222-222222222215', 'short', '𝑛= 1 时，𝑎1 = 𝑆1 = 𝐴+ 𝐵.', null, '', '', '数学/第5章 数列（1）.pdf', 9, true, 74, null),
  ('b1336cb8-56c6-564a-86ba-d09820b7fe56', '22222222-2222-2222-2222-222222222215', 'short', '𝑛⩾2 时，𝑎𝑛= 𝑆𝑛−𝑆𝑛−1 = 𝐴𝑛2 + 𝐵𝑛−[𝐴(𝑛−1)2 + 𝐵(𝑛−1)] = 𝐴𝑛2 + 𝐵𝑛−[𝐴𝑛2 −2𝐴𝑛+ 𝐴+ 𝐵𝑛−𝐵] = 2𝐴𝑛−𝐴+ 𝐵. 综上：𝑎𝑛= 2𝐴𝑛−𝐴+ 𝐵 (𝑛= 1,2,3,4, ⋯)是等差数列. 证明：𝑎𝑛是等差数列 ⇒ 𝑆𝑛= 𝐴𝑛2 + 𝐵𝑛 设𝑎𝑛= 𝑎1 + (𝑛−1)𝑑，则𝑆𝑛= 𝑛(𝑎1 + 𝑎𝑛) 2 = 𝑛[𝑎1 + 𝑎1 + (𝑛−1)𝑑] 2 = 𝑛𝑎1 + 𝑛(𝑛−1)𝑑 2 = 𝑑 2 𝑛2 + (𝑎1 −𝑑', null, '', '', '数学/第5章 数列（1）.pdf', 9, true, 75, null),
  ('f13c0b1d-5499-5772-89c3-26fbdb6e450c', '22222222-2222-2222-2222-222222222215', 'short', '𝑛 记𝐴= 𝑑 2 ，𝐵= 𝑎1 − 𝑑 2 ，则𝑆𝑛= 𝐴𝑛2 + 𝐵𝑛. 证毕. 【注】当𝒏为奇数的时候，𝑺𝒏= 𝒏𝒂𝒏+𝟏 𝟐，其中𝒂𝒏+𝟏 𝟐是数列𝒂𝟏, 𝒂𝟐, 𝒂𝟑, ⋯, 𝒂𝒏 的中间项. 例如𝑺𝟓= 𝒏𝒂𝟑. 你的坚持，终将美好！ 8 题型4：考查𝑺𝒏的性质', null, '', '', '数学/第5章 数列（1）.pdf', 9, true, 76, null),
  ('b4c71665-e778-56c7-bc60-5729f542077b', '22222222-2222-2222-2222-222222222215', 'mcq', '已知等差数列{𝑎𝑛}的前𝑛项和为𝑆𝑛，𝑆5 = 15, 𝑆15 = 120，则𝑆10 = ( ).', '[{"key": "A", "text": "40"}, {"key": "B", "text": "45"}, {"key": "C", "text": "50"}, {"key": "D", "text": "55"}, {"key": "E", "text": "60"}]'::jsonb, '', '', '数学/第5章 数列（1）.pdf', 10, true, 77, null),
  ('ec0ca203-ac6c-5fd0-8380-13db880e6d4f', '22222222-2222-2222-2222-222222222215', 'short', '设数列{𝑎𝑛}的前𝑛项和为𝑆𝑛，则数列{𝑎𝑛}是等差数列.', null, '', '', '数学/第5章 数列（1）.pdf', 10, true, 78, null),
  ('f53dde20-9389-52df-b96b-54809b978e66', '22222222-2222-2222-2222-222222222215', 'short', '𝑆𝑛= 𝑛2 + 2𝑛, 𝑛= 1,2,3, ⋯. （2）𝑆𝑛= 𝑛2 + 2𝑛+ 1, 𝑛= 1,2,3, ⋯. 你的坚持，终将美好！ 9 四、等差数列{𝒂𝒏}的重要性质', null, '', '', '数学/第5章 数列（1）.pdf', 10, true, 79, null),
  ('a94295f3-3007-5ccb-b8cb-b0fa796e973b', '22222222-2222-2222-2222-222222222215', 'short', '𝑎𝑛= 𝑎𝑚+ (𝑛−𝑚)𝑑 ⇒ 𝑑= 𝑎𝑛−𝑎𝑚 𝑛−𝑚.', null, '', '', '数学/第5章 数列（1）.pdf', 11, true, 80, null),
  ('22c15bce-bd6b-562a-8bd4-7ee1830d5bc4', '22222222-2222-2222-2222-222222222215', 'short', '若𝑎, 𝑏, 𝑐成等差数列，则称𝑏是𝑎, 𝑐的等差中项，且2𝑏= 𝑎+ 𝑐.', null, '', '', '数学/第5章 数列（1）.pdf', 11, true, 81, null),
  ('13add8f1-75f3-51d7-b76d-c82995f0af0d', '22222222-2222-2222-2222-222222222215', 'short', '若𝑚, 𝑛, 𝑙, 𝑘, (𝑘∈𝑁+)，且𝑚+ 𝑛= 𝑙+ 𝑘，则𝑎𝑚+ 𝑎𝑛= 𝑎𝑙+ 𝑎𝑘. 特别地，若𝑚+ 𝑛= 2𝑝，则𝑎𝑚+ 𝑎𝑛= 𝑎𝑝+ 𝑎𝑝= 2𝑎𝑝（☆☆☆）. 简记为，若项数相等，则项和相等（可拓展至多项）. 推导： 𝑎𝑚= 𝑎1 + (𝑚−1)𝑑，𝑎𝑛= 𝑎1 + (𝑛−1)𝑑， 𝑎𝑙= 𝑎1 + (𝑙−1)𝑑，𝑎𝑘= 𝑎1 + (𝑘−1)𝑑 𝑎𝑚+ 𝑎𝑛= 𝑎1 + (𝑚−1)𝑑+ 𝑎1 + (𝑛−1)𝑑= 2𝑎1 + (𝑚+ 𝑛)𝑑−2𝑑 𝑎𝑙+ 𝑎𝑘= 𝑎1 + (𝑙−1)𝑑+ 𝑎1 + (𝑘−1)𝑑= 2𝑎1 + (𝑙+ 𝑘)𝑑−2𝑑 两式对比：区别在𝑚+ 𝑛与𝑙+ 𝑘， 所以𝑚+ 𝑛= 𝑙+ 𝑘，则有𝑎𝑚+ 𝑎𝑛= 𝑎𝑙+ 𝑎𝑘.', null, '', '', '数学/第5章 数列（1）.pdf', 11, true, 82, null),
  ('b07670b7-7232-5744-b8f3-7800c2400688', '22222222-2222-2222-2222-222222222215', 'short', '若等差数列{𝑎𝑛}的公差为𝑑，则数列{𝜆𝑎𝑛± 𝑏}(𝜆, 𝑏为常数)是公差为𝜆𝑑 的等差数列（☆）. 推导： 设等差数列𝑎𝑛= 𝑎1 + (𝑛−1)𝑑，记𝑏𝑛= 𝜆𝑎𝑛+ 𝑏 则𝑏𝑛−𝑏𝑛−1 = 𝜆𝑎𝑛+ 𝑏−(𝜆𝑎𝑛−1 + 𝑏) = 𝜆(𝑎𝑛−𝑎𝑛−1) = 𝜆𝑑. 你的坚持，终将美好！ 10', null, '', '', '数学/第5章 数列（1）.pdf', 11, true, 83, null),
  ('b4286a84-279c-5f90-905c-5a18ada9180d', '22222222-2222-2222-2222-222222222215', 'short', '若{𝑎𝑛}和{𝑏𝑛}均为等差数列，公差为𝑑𝑎, 𝑑𝑏，则{𝑘𝑎𝑛± 𝑙𝑏𝑛}(𝑘, 𝑙为常数) 也是等差数列. 公差为𝑘𝑑𝑎± 𝑙𝑑𝑏. 推导： 𝑘𝑎𝑛+ 𝑙𝑏𝑛−(𝑘𝑎𝑛−1 + 𝑙𝑏𝑛−1) = 𝑘(𝑎𝑛−𝑎𝑛−1) + 𝑙(𝑏𝑛−𝑏𝑛−1) = 𝑘𝑑𝑎+ 𝑙𝑑𝑏. 𝑎𝑛 1 2 3 4 5 ⋯ 𝑑= 1 𝑏𝑛 2 4 6 8 10 ⋯ 𝑑= 2 𝑎𝑛+ 𝑏𝑛 3 6 9 12 15 ⋯ 𝑑= 3 2𝑎𝑛+ 𝑏𝑛 4 8 12 16 20 ⋯ 𝑑= 4', null, '', '', '数学/第5章 数列（1）.pdf', 12, true, 84, null),
  ('56cfa617-e0f9-5d12-9b6b-7ad849a08ba1', '22222222-2222-2222-2222-222222222215', 'short', '若𝑆𝑛为等差数列的前𝑛项和，则𝑆𝑛, 𝑆2𝑛−𝑆𝑛, 𝑆3𝑛−𝑆2𝑛, ⋯，仍为等差数列， 其公差为𝑛2𝑑. 𝑎1 𝑎2 𝑎3 𝑎4 𝑎5 𝑎6 𝑎7 𝑎8 𝑎9 你的坚持，终将美好！ 11', null, '', '', '数学/第5章 数列（1）.pdf', 12, true, 85, null),
  ('b1ce3dcd-6709-5ec3-a26e-65e5f035ff86', '22222222-2222-2222-2222-222222222215', 'short', '若数列{𝑎𝑛}和{𝑏𝑛}均为等差数列，其前项和分别为𝑆𝑛, 𝑇𝑛，则有 𝑆2𝑛−1 𝑇2𝑛−1 = 𝑎𝑛 𝑏𝑛. 推导： 𝑆2𝑛−1 = (2𝑛−1)(𝑎1 + 𝑎2𝑛−1) 2 ；𝑇2𝑛−1 = (2𝑛−1)(𝑏1 + 𝑏2𝑛−1) 2 𝑆2𝑛−1 𝑇2𝑛−1 = (2𝑛−1)(𝑎1 + 𝑎2𝑛−1)/2 (2𝑛−1)(𝑏1 + 𝑏2𝑛−1)/2 = 𝑎1 + 𝑎2𝑛−1 𝑏1 + 𝑏2𝑛−1 = 𝑎𝑛+ 𝑎𝑛 𝑏𝑛+ 𝑏𝑛 = 𝑎𝑛 𝑏𝑛 .', null, '', '', '数学/第5章 数列（1）.pdf', 13, true, 86, null),
  ('716a228d-1d0f-5a89-9581-b33e8b182448', '22222222-2222-2222-2222-222222222215', 'short', '等差数列的等价表述 数列{𝑎𝑛}为等差数列⇔𝑎𝑛+1 −𝑎𝑛= 𝑑 (𝑑为常数，𝑛为正整数). ⇔𝑎𝑛= 𝐴𝑛+ 𝐵 (𝐴, 𝐵为常数). ⇔2𝑎𝑛+1 = 𝑎𝑛+ 𝑎𝑛+2. ⇔𝑆𝑛= 𝐴𝑛2 + 𝐵𝑛 (𝐴, 𝐵为常数). 题型5：考查等差数列的性质', null, '', '', '数学/第5章 数列（1）.pdf', 13, true, 87, null),
  ('7b7d0767-9e8d-5dfe-81a8-e88a00693cf7', '22222222-2222-2222-2222-222222222215', 'mcq', '已知等差数列{𝑎𝑛}中，𝑎1和𝑎10是方程𝑥2 −3𝑥−5 = 0的两根，那么 𝑎3 + 𝑎8 = ( ).', '[{"key": "A", "text": "3 或−3"}, {"key": "B", "text": "4"}, {"key": "C", "text": "3"}, {"key": "D", "text": "−3"}, {"key": "E", "text": "−4"}]'::jsonb, '', '', '数学/第5章 数列（1）.pdf', 13, true, 88, null),
  ('fc5330a9-adb1-59aa-9c8a-4d39c049029a', '22222222-2222-2222-2222-222222222215', 'mcq', '等差数列{𝑎𝑛}中，𝑎1 + 𝑎5 = 10，𝑎4 = 7，则数列{𝑎𝑛}的公差为( ).', '[{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}, {"key": "D", "text": "4"}, {"key": "E", "text": "5"}]'::jsonb, '', '', '数学/第5章 数列（1）.pdf', 14, true, 89, null),
  ('d23c700c-22f1-5640-81c6-b09749faa9df', '22222222-2222-2222-2222-222222222215', 'short', '设{𝑎𝑛}是等差数列，则能确定数列{𝑎𝑛}.', null, '', '', '数学/第5章 数列（1）.pdf', 14, true, 90, null),
  ('e5960e78-44bc-5b0d-9805-ed60f95de2cd', '22222222-2222-2222-2222-222222222215', 'short', '𝑎1 + 𝑎6 = 0.', null, '', '', '数学/第5章 数列（1）.pdf', 14, true, 91, null),
  ('7bbc4a03-c6fd-55c0-8339-aff40f3c1090', '22222222-2222-2222-2222-222222222215', 'short', '𝑎1𝑎6 = −1. 你的坚持，终将美好！ 13 题型7：考查数列前𝒏项和的确定', null, '', '', '数学/第5章 数列（1）.pdf', 14, true, 92, null),
  ('1bc14110-f94d-5b26-aaa4-58bb83aff4b0', '22222222-2222-2222-2222-222222222215', 'short', '设{𝑎𝑛}是等差数列，则能确定𝑎1 + 𝑎2 + ⋯+ 𝑎9的值.', null, '', '', '数学/第5章 数列（1）.pdf', 15, true, 93, null),
  ('646f1578-677a-53fd-8d62-34badb79c51d', '22222222-2222-2222-2222-222222222215', 'short', '已知𝑎1的值.', null, '', '', '数学/第5章 数列（1）.pdf', 15, true, 94, null),
  ('bc303dc0-366d-55dd-bfa2-fa4fb7c5abb8', '22222222-2222-2222-2222-222222222215', 'short', '已知𝑎5的值. 你的坚持，终将美好！ 14 考点3：等比数列 一、定义 如果一个数列从第2 项起，每一项与它前一项的比值等于同一个常数，那 么这个数列就叫作等比数列，这个常数叫做等比数列的公比，公比通常用 字母𝑞(𝑞≠0)表示，即 𝑎𝑛+1 𝑎𝑛= 𝑞(𝑞≠0, 𝑛∈𝑁+). 特别地，𝑞= 1时，数列为 常数列. 二、通项公式', null, '', '', '数学/第5章 数列（1）.pdf', 15, true, 95, null),
  ('4102343d-9318-50d7-b247-ee4f47aa7b08', '22222222-2222-2222-2222-222222222215', 'short', '基本公式：𝑎𝑛= 𝑎1𝑞𝑛−1.', null, '', '', '数学/第5章 数列（1）.pdf', 16, true, 96, null),
  ('7b0e2268-a06c-5698-8038-7fdf16aa8301', '22222222-2222-2222-2222-222222222215', 'short', '拓展公式：𝑎𝑛= 𝑎𝑚𝑞𝑛−𝑚. 题型1：考查等比数列的通项', null, '', '', '数学/第5章 数列（1）.pdf', 16, true, 97, null),
  ('aa216c2e-0108-5ec4-a67e-42a6899ab337', '22222222-2222-2222-2222-222222222215', 'mcq', '设等比数列{𝑎𝑛}的公比为正数，且𝑎3𝑎9 = 2𝑎5 2, 𝑎2 = 1，则𝑎1 = ( ).', '[{"key": "A", "text": "1 2"}, {"key": "B", "text": "√2 2"}, {"key": "C", "text": "√2"}, {"key": "D", "text": "2"}, {"key": "E", "text": "4 你的坚持，终将美好！ 15"}]'::jsonb, '', '', '数学/第5章 数列（1）.pdf', 16, true, 98, null),
  ('c26a434e-c8e6-5dba-be66-a0ecc00c1b76', '22222222-2222-2222-2222-222222222215', 'mcq', '若方程(𝑎2 + 𝑐2)𝑥2 −2𝑐(𝑎+ 𝑏)𝑥+ 𝑏2 + 𝑐2 = 0有实根，则( ).', '[{"key": "A", "text": "𝑎, 𝑏, 𝑐成等比数列"}, {"key": "B", "text": "𝑎, 𝑐, 𝑏成等比数列"}, {"key": "C", "text": "𝑏, 𝑎, 𝑐成等比数列"}, {"key": "D", "text": "𝑎, 𝑏, 𝑐成等差数列"}, {"key": "E", "text": "𝑏, 𝑎, 𝑐成等差数列"}]'::jsonb, '', '', '数学/第5章 数列（1）.pdf', 17, true, 99, null),
  ('c5ddea7c-a626-5495-9448-f75ae13f3848', '22222222-2222-2222-2222-222222222215', 'short', '等比数列{𝑎𝑛}满足𝑎2 + 𝑎4 = 20，则𝑎3 + 𝑎5 = 40.', null, '', '', '数学/第5章 数列（1）.pdf', 17, true, 100, null),
  ('6f5b97e2-6a8b-50a9-bc54-85fc09385c33', '22222222-2222-2222-2222-222222222215', 'short', '公比𝑞= 2.', null, '', '', '数学/第5章 数列（1）.pdf', 17, true, 101, null),
  ('07f41ab6-e242-5540-8dda-306e2c5f833e', '22222222-2222-2222-2222-222222222215', 'short', '𝑎1 + 𝑎3 = 10. 你的坚持，终将美好！ 16 三、等比数列的求和公式', null, '', '', '数学/第5章 数列（1）.pdf', 17, true, 102, null),
  ('15382a9c-c2bb-50ce-88e6-7f69e687bd2a', '22222222-2222-2222-2222-222222222215', 'short', '前𝑛项和𝑆𝑛公式 𝑆𝑛= { 𝑛𝑎1, 𝑞= 1, 𝑎1(1 −𝑞𝑛) 1 −𝑞 = 𝑎1 −𝑎1𝑞𝑛 1 −𝑞 = 𝑎1 −𝑎𝑛𝑞 1 −𝑞 , 𝑞≠0 且𝑞≠1.', null, '', '', '数学/第5章 数列（1）.pdf', 18, true, 103, null),
  ('dab94340-fe24-5f68-9426-ad10c152be93', '22222222-2222-2222-2222-222222222215', 'short', '当𝑞≠0且𝑞≠1时， 𝑆𝑚 𝑆𝑛= 1−𝑞𝑚 1−𝑞𝑛.', null, '', '', '数学/第5章 数列（1）.pdf', 18, true, 104, null),
  ('02ac2e6f-a588-5ab4-b897-1087979eeacf', '22222222-2222-2222-2222-222222222215', 'short', '所有项和𝑆公式 对于无穷(𝑛→+∞)递减等比数列(|𝑞| < 1, 𝑞≠0)，所有项和为𝑆= 𝑎1 1−𝑞. 你的坚持，终将美好！ 17 题型2：考查等比数列𝑺𝒏的求解', null, '', '', '数学/第5章 数列（1）.pdf', 18, true, 105, null),
  ('8da507ed-5097-5629-a670-7080561d4950', '22222222-2222-2222-2222-222222222215', 'mcq', '某人在保险柜中存放了𝑀元现金，第一天取出它的 2 3，以后每天取出前 一天所取的 1 3，共取了7 次，保险柜中剩余的现金为( )元.', '[{"key": "A", "text": "𝑀 37"}, {"key": "B", "text": "𝑀 36"}, {"key": "C", "text": "2𝑀 36"}, {"key": "D", "text": "[1 −(2 3) 7 ] 𝑀"}, {"key": "E", "text": "[1 −7 (2 3) 7 ] 𝑀"}]'::jsonb, '', '', '数学/第5章 数列（1）.pdf', 19, true, 106, null),
  ('d098db50-44c9-51da-bca1-175b6aec3e70', '22222222-2222-2222-2222-222222222215', 'mcq', '一个球从100 米高处自由落下，每次着地后又跳回前一次高度的一半 再落下，当它第10 次着地时，共经过的路程约是( )米.（精确到1 米且不计任何阻力）', '[{"key": "A", "text": "350"}, {"key": "B", "text": "300"}, {"key": "C", "text": "250"}, {"key": "D", "text": "200"}, {"key": "E", "text": "150"}]'::jsonb, '', '', '数学/第5章 数列（1）.pdf', 19, true, 107, null),
  ('0dd35970-c4fc-5c2b-a1c5-5f7edc543b84', '22222222-2222-2222-2222-222222222216', 'short', '𝑎𝑛= {𝑎1, 𝑛= 1, 𝑆𝑛−𝑆𝑛−1, 𝑛⩾2.', null, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 1, null),
  ('d9944d9d-1880-53af-80b2-4ef886d87798', '22222222-2222-2222-2222-222222222216', 'short', '等差数列：𝑎𝑛= 𝑎1 + (𝑛−1)𝑑= 𝑎𝑘+ (𝑛−𝑘)𝑑.', null, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 2, null),
