  ('ac45c818-094f-59be-baad-c83fef9ca655', '22222222-2222-2222-2222-222222222216', 'short', '加浓问题：特点是增加“溶质”，找不变量“溶剂”. 题型1：考查蒸发情形（溶质守恒）', null, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 20, null),
  ('5b5e1cc0-1127-5091-a96d-03df0405e1a1', '22222222-2222-2222-2222-222222222216', 'mcq', '含盐12.5%的盐水40千克蒸发掉部分水分后变成了含盐20%的盐水， 蒸发掉的水分质量为( )千克.', '[{"key": "A", "text": "19"}, {"key": "B", "text": "18"}, {"key": "C", "text": "17"}, {"key": "D", "text": "16"}, {"key": "E", "text": "15"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 21, null),
  ('6331c0e5-e899-560d-9785-1eaa05fa72e6', '22222222-2222-2222-2222-222222222216', 'mcq', '若用浓度为30%和20%的甲、乙两种食盐溶液配成浓度为24%的食盐 溶液500 克，则甲、乙两种溶液各取( ).', '[{"key": "A", "text": "180 克，320 克"}, {"key": "B", "text": "200 克，300 克"}, {"key": "C", "text": "190 克，310 克"}, {"key": "D", "text": "195 克，305 克"}, {"key": "E", "text": "185 克，315 克"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 7, true, 22, null),
  ('44dc02a8-6c3b-509f-b985-ad407a0f8277', '22222222-2222-2222-2222-222222222216', 'mcq', '车间共有40 人，某技术操作考核的平均成绩为80 分，其中男工平均 成绩为83 分，女工平均成绩为78 分.该车间有女工( )人.', '[{"key": "A", "text": "36"}, {"key": "B", "text": "30"}, {"key": "C", "text": "28"}, {"key": "D", "text": "24"}, {"key": "E", "text": "20"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 23, null),
  ('17ce6aea-af5c-5379-b6a7-8686f3500cca', '22222222-2222-2222-2222-222222222216', 'mcq', '甲杯中有纯酒精12克，乙杯中有水15克，第一次，将甲杯中部分酒精 倒入乙杯中。第二次，将乙杯中部分溶液倒入甲杯中。这时，测得甲 杯中溶液浓度为50% ，乙杯中溶液浓度为25% 。则第二次操作中，乙 杯倒入甲杯溶液为( )克.（难）', '[{"key": "A", "text": "13"}, {"key": "B", "text": "14"}, {"key": "C", "text": "15"}, {"key": "D", "text": "16"}, {"key": "E", "text": "17"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 24, null),
  ('6b8d84c0-fe31-5b16-9f1b-bc7d6e042b83', '22222222-2222-2222-2222-222222222216', 'short', '…… 你的坚持，终将美好！ 13 题型3：考查溶液置换', null, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 11, true, 25, null),
  ('d9d570e8-4ff7-5c52-9d3d-a5c1bf6510b9', '22222222-2222-2222-2222-222222222216', 'mcq', '某容器中装满了浓度为90%的酒精，倒出1 升后用水将容器注满，搅 拌均匀后又倒出1 升，再用水将容器注满.已知此时的酒精浓度为40%， 则该容器的容积为( ).', '[{"key": "A", "text": "2.5 升"}, {"key": "B", "text": "3 升"}, {"key": "C", "text": "3.5 升"}, {"key": "D", "text": "4.5 升"}, {"key": "E", "text": "4 升"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 12, true, 26, null),
  ('136b61e4-0da3-5727-a72e-8a5c67a64407', '22222222-2222-2222-2222-222222222216', 'mcq', '某班同学在一次测试中，平均成绩为75 分，其中男同学人数比女同学 人数多80%，而女同学的平均成绩比男同学的高20%，则女同学的平 均成绩为( ).', '[{"key": "A", "text": "83 分"}, {"key": "B", "text": "84 分"}, {"key": "C", "text": "85 分"}, {"key": "D", "text": "86 分"}, {"key": "E", "text": "87 分"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 14, true, 27, null),
  ('80f500a4-9cca-5619-aa0d-d8807cda7a47', '22222222-2222-2222-2222-222222222216', 'short', '路程=速度×时间，( 𝑠= 𝑣𝑡 ). 时间= 路程 速度，( 𝑡= 𝑠 𝑣 ). 速度= 路程 时间，( 𝑣= 𝑠 𝑡 ). 𝑠一定时，𝑣和𝑡成反比；𝑡一定时，𝑠和𝑣成正比；𝑣一定时，𝑠和𝑡成正比.', null, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 15, true, 28, null),
  ('3996bc4b-cc90-5bab-b89c-7c488b20dfc0', '22222222-2222-2222-2222-222222222216', 'short', '等距离平均速度公式：𝑣= 2𝑣1𝑣2 𝑣1+𝑣2，𝑣1, 𝑣2分别是来时和去时的速度. 适用：直线等距离，直线往返，上下坡往返. 推导：直线往返为例 不妨设单程路程为𝑠，来时速度为𝑣1，去时速度为𝑣2 来时时间：𝑡1 = 𝑠 𝑣1 ；去时时间：𝑡2 = 𝑠 𝑣2 总路程为2𝑠，总时间𝑡= 𝑡1 + 𝑡2 = 𝑠 𝑣1 + 𝑠 𝑣2 = (𝑣1 + 𝑣2)𝑠 𝑣1𝑣2 ， 全程平均速度为𝑣= 2𝑠 𝑡= 2𝑠 (𝑣1 + 𝑣2)𝑠 𝑣1𝑣2 = 2𝑣1𝑣2 𝑣1 + 𝑣2 . 你的坚持，终将美好！ 17 题型1：考查普通行程问题', null, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 15, true, 29, null),
  ('f1ccf752-b13d-5afb-8970-e4ca6e27d448', '22222222-2222-2222-2222-222222222216', 'short', '某人从𝐴地出发，先乘时速为220 千米的动车，后转乘时速为100 千 米的汽车到达𝐵地，则𝐴, 𝐵两地的距离为960 千米.', null, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, true, 30, null),
  ('081f871c-7789-5f82-95dd-f94b1efceb36', '22222222-2222-2222-2222-222222222216', 'short', '乘动车时间与乘汽车的时间相等.', null, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, true, 31, null),
  ('2f62fe7c-0116-5668-b33b-e770f0793699', '22222222-2222-2222-2222-222222222216', 'short', '乘动车时间与乘汽车的时间之和为6 小时. 题型2：考查等距离求平均速度', null, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, true, 32, null),
  ('2d890606-cbda-5cd6-bcba-6d2a04122993', '22222222-2222-2222-2222-222222222216', 'mcq', '某人以6 公里/小时的平均速度上山，上山后立即以12 公里/小时的平 均速度原路返回，那么此人在往返过程中每小时平均所走的公里数为 ( ).', '[{"key": "A", "text": "9"}, {"key": "B", "text": "8"}, {"key": "C", "text": "7"}, {"key": "D", "text": "6"}, {"key": "E", "text": "5"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, true, 33, null),
  ('24ea6158-68c8-523d-93b2-94719bb8b862', '22222222-2222-2222-2222-222222222216', 'short', '一次相遇：相遇1 次，则走1 个全程. 𝑆= 𝑆1 + 𝑆2 = 𝑣1𝑡+ 𝑣2𝑡= (𝑣1 + 𝑣2)𝑡 , 𝑡= 𝑆 𝑣1 + 𝑣2 . 𝑆1 𝑆2 A B 多次相遇：相遇2次，则走3 个全程，则3𝑆= (𝑣1 + 𝑣2)𝑡 , 𝑡= 3𝑆 𝑣1+𝑣2. 𝑆1 𝑆2 A B 相遇𝑛次，则走2𝑛−1个全程，则(2𝑛−1)𝑆= (𝑣1 + 𝑣2)𝑡. 相遇一起走的路程和时间满足：1：3：5：7……', null, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 18, true, 34, null),
  ('b3335083-2475-52e8-91cc-c948b4a31eb2', '22222222-2222-2222-2222-222222222216', 'short', '追及：𝑆距离差= 𝑆1 −𝑆2 = 𝑣1𝑡−𝑣2𝑡= (𝑣1 −𝑣2)𝑡 , 𝑡= 𝑆距离差 𝑣1−𝑣2. 𝑆1 A B A、B 𝑆2 你的坚持，终将美好！ 20 题型3：考查一次相遇问题', null, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 18, true, 35, null),
  ('c39e51a6-660d-5e2f-84a6-3d196174e798', '22222222-2222-2222-2222-222222222216', 'mcq', '甲、乙两车同时从𝐴, 𝐵两地相向开出，甲车行驶速度为70km/h，乙车 每小时行驶62km/h，两辆车在离中点20km 处相遇，则𝐴, 𝐵两地相距 ( )km.', '[{"key": "A", "text": "660"}, {"key": "B", "text": "330"}, {"key": "C", "text": "300"}, {"key": "D", "text": "600"}, {"key": "E", "text": "570"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 19, true, 36, null),
  ('5b44d766-efe7-5ff4-b8d7-81079183b6df', '22222222-2222-2222-2222-222222222216', 'mcq', '甲、乙两列火车分别从𝐴城，𝐵城相向而行，第一次相遇在离𝐴地500 公 里处，相遇后，两列车继续前进，各自到达目的地后，又折回，第二 次相遇在离𝐵城300 公里处，问𝐴城，𝐵城相距( )公里.', '[{"key": "A", "text": "600"}, {"key": "B", "text": "800"}, {"key": "C", "text": "1000"}, {"key": "D", "text": "1200"}, {"key": "E", "text": "1500"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 19, true, 37, null),
  ('efcfd479-435e-5846-97ad-91a3d7a83fb1', '22222222-2222-2222-2222-222222222216', 'mcq', '甲、乙两人从同一地点出发，甲先出发10 分钟.若乙跑步追赶甲，则10 分钟追上；若乙骑车追赶甲，每分钟比跑步多行100 米，则5 分钟追 上.那么甲每分钟走的距离为( )米.', '[{"key": "A", "text": "50"}, {"key": "B", "text": "75"}, {"key": "C", "text": "100"}, {"key": "D", "text": "125"}, {"key": "E", "text": "150"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, true, 38, null),
  ('8a06d1b9-dafa-5f77-9f92-767d43d7d6b4', '22222222-2222-2222-2222-222222222216', 'mcq', '甲、乙两人同时从A 点出发,沿400 米跑道同向均匀行走,25 分钟后乙 比甲少走了一圈.若乙行走一圈需要8 分钟,则甲的速度是( )米/分钟.', '[{"key": "A", "text": "62"}, {"key": "B", "text": "65"}, {"key": "C", "text": "66"}, {"key": "D", "text": "67"}, {"key": "E", "text": "69"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, true, 39, null),
  ('91eba894-f34f-5f1d-a4dc-32114713a57c', '22222222-2222-2222-2222-222222222216', 'mcq', '已知船在静水中的速度为25 千米/小时，水流的速度为15 千米/小时， 则此船在相距80 千米的两地间往返一次所需要的时间是( )小时.', '[{"key": "A", "text": "8"}, {"key": "B", "text": "10"}, {"key": "C", "text": "12"}, {"key": "D", "text": "14"}, {"key": "E", "text": "16"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 23, true, 40, null),
