  ('3974b735-a425-5310-ad66-55367fe3c2e7', '22222222-2222-2222-2222-222222222216', 'short', '𝑣−𝑡图：横坐标代表时间，纵坐标代表速度，图形与𝑥轴围成的面积代表 路程. 题型9：考查数形结合', null, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 26, true, 48, null),
  ('7dac912a-2128-5f59-9b69-c4545a3aa006', '22222222-2222-2222-2222-222222222216', 'mcq', '货车行驶72km用时1h，其速度𝑣与行驶时间𝑡的关系如图所示，则𝑣0 = ( )km/h.', '[{"key": "A", "text": "72"}, {"key": "B", "text": "80"}, {"key": "C", "text": "90"}, {"key": "D", "text": "95"}, {"key": "E", "text": "100"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 26, true, 49, null),
