  ('8e2d08d3-e448-55ae-9468-9d241fa88956', '22222222-2222-2222-2222-222222222216', 'short', '这片草地可供30 头牛吃多少天？（9）', null, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 7, true, 72, null),
