  ('7a506056-b918-5065-9da4-3fc1dd950b74', '22222222-2222-2222-2222-222222222216', 'mcq', '牧场上一片青草，每天牧草都均匀生长。这片牧草可供100 头牛吃20 天，或者可供150 头牛吃10 天。则这片牧场可供250 头牛吃( )天.', '[{"key": "A", "text": "5"}, {"key": "B", "text": "6"}, {"key": "C", "text": "7"}, {"key": "D", "text": "8"}, {"key": "E", "text": "9"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 74, null),
  ('32d1fc27-ea0f-5ba9-948a-9725ea8206e2', '22222222-2222-2222-2222-222222222216', 'mcq', '某道路一侧原有路灯106 盏，道路两端均设有路灯，相邻两盏灯的距 离为36m，现将原有路灯全部换为新型节能灯，两灯距离变为70m， 道路两端依旧各装一盏路灯，布局不超出原道路范围，则道路一侧共需 新型节能灯( )盏.', '[{"key": "A", "text": "54"}, {"key": "B", "text": "55"}, {"key": "C", "text": "108"}, {"key": "D", "text": "110"}, {"key": "E", "text": "112"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 10, true, 75, null),
  ('acd47185-00ae-504c-a054-8911129eb138', '22222222-2222-2222-2222-222222222216', 'mcq', '将一批树苗种在一个正方形花园的边上，四角都种.如果每隔3m 种一 棵，那么剩下10 棵树苗；如果每隔2m 种一棵，那么恰好种满正方形 的3 条边，则这批树苗有( )棵.', '[{"key": "A", "text": "54"}, {"key": "B", "text": "60"}, {"key": "C", "text": "70"}, {"key": "D", "text": "82"}, {"key": "E", "text": "94"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 10, true, 76, null),
  ('16a00553-7707-5a54-9b91-68697d57a3d3', '22222222-2222-2222-2222-222222222216', 'short', '𝐴+ 𝐵−𝐴∩𝐵= 𝐴∪𝐵 二、三集合公式', null, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 12, true, 77, null),
  ('454fbbe8-ea42-5c90-8624-c08797ba1abf', '22222222-2222-2222-2222-222222222216', 'short', '𝐴+ 𝐵+ 𝐶−𝑎−𝑏−𝑐−2𝑑= 𝐴∪𝐵∪𝐶', null, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 12, true, 78, null),
  ('8dc21c47-329a-56c6-8641-945513bda3fb', '22222222-2222-2222-2222-222222222216', 'short', '𝐴+ 𝐵+ 𝐶−𝐴∩𝐵−𝐴∩𝐶−𝐵∩𝐶+ 𝐴∩𝐵∩𝐶= 𝐴∪𝐵∪𝐶 你的坚持，终将美好！ 30 题型1：考查两集合问题', null, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 12, true, 79, null),
  ('aa0f575c-ef67-572a-9405-f120083037fd', '22222222-2222-2222-2222-222222222216', 'mcq', '某单位有职工40 人，其中参加计算机考核的有31 人，参加外语考核 的有20 人，有8 人没有参加任何一种考核，则同时参加两项考核的职 工有( )人.', '[{"key": "A", "text": "10"}, {"key": "B", "text": "13"}, {"key": "C", "text": "15"}, {"key": "D", "text": "19"}, {"key": "E", "text": "20"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 13, true, 80, null),
  ('1a6da806-0d0b-54dc-aec5-e879e01e25d2', '22222222-2222-2222-2222-222222222216', 'mcq', '某单位有240 名员工，其中订阅𝐴期刊的有125 人，订阅𝐵期刊的有 126 人，订阅𝐶期刊的有135 人，订阅𝐴、𝐵期刊的有57 人，订阅𝐴、𝐶 期刊的有73 人，订阅3 种期刊的有31 人，此外，还有17 人没有订 阅这三种期刊中的任何一种。则订阅𝐵、𝐶期刊的有( )人.', '[{"key": "A", "text": "57"}, {"key": "B", "text": "64"}, {"key": "C", "text": "69"}, {"key": "D", "text": "78"}, {"key": "E", "text": "81"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 13, true, 81, null),
  ('104cce50-d834-54d4-bc6c-f0a0a499abc6', '22222222-2222-2222-2222-222222222216', 'mcq', '某公司的员工中，拥有本科毕业证、计算机等级证、汽车驾驶证的人数 分别为130，110，90，又知只有一种证的人数为140，三证齐全的人 数为30，则恰有双证的人数为( ).', '[{"key": "A", "text": "45"}, {"key": "B", "text": "50"}, {"key": "C", "text": "52"}, {"key": "D", "text": "65"}, {"key": "E", "text": "100"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 14, true, 82, null),
  ('b866150d-4383-5914-a101-537de5209254', '22222222-2222-2222-2222-222222222216', 'mcq', '某公司用1 万元购买了价格分别是1750 元和950 元的甲、乙两种办 公设备，则购买的甲、乙办公设备的件数分别为( ).', '[{"key": "A", "text": "3,5"}, {"key": "B", "text": "5,3"}, {"key": "C", "text": "4,4"}, {"key": "D", "text": "2,6"}, {"key": "E", "text": "6,2"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, true, 83, null),
  ('f3ad9eb8-3315-5965-bfc8-eb38d5a0a1dc', '22222222-2222-2222-2222-222222222216', 'mcq', '某单位向希望工程捐款，其中部门领导每人捐50 元，普通员工每人捐 20 元，某部门所有人员共捐款320 元，已知该部门总人数超过10 人， 则该部门可能有( )名部门领导.', '[{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}, {"key": "D", "text": "4"}, {"key": "E", "text": "5"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, true, 84, null),
  ('dd33d3d3-8e43-517b-a92f-d6b64c9adabf', '22222222-2222-2222-2222-222222222216', 'mcq', '有271 位游客欲乘大、小两种客车旅游，已知大客车有37 个座位，小 客车有20 个座位. 为保证每位游客均有座位，且车上没有空座位，则 需要大客车的辆数是( ).', '[{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}, {"key": "D", "text": "4"}, {"key": "E", "text": "5"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 17, true, 85, null),
  ('83d9c6c4-7c51-5127-aaf8-4392ea10530f', '22222222-2222-2222-2222-222222222216', 'mcq', '某自来水公司的水费计算方法如下：每户每月用水不超过5 吨的，每 吨收费4 元，超过5 吨的，每吨收取较高标准的费用.已知9 月份张家 的用水量比李家的用水量多50%，张家和李家的水费分别是90 元和 55 元，则用水量超过5 吨的收费标准是( )元/吨.', '[{"key": "A", "text": "5"}, {"key": "B", "text": "5.5"}, {"key": "C", "text": "6"}, {"key": "D", "text": "6.5"}, {"key": "E", "text": "7"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 19, true, 86, null),
  ('5b9e0188-adba-5395-a930-64791d11dae3', '22222222-2222-2222-2222-222222222216', 'short', '同比是指本年度（季度，月份）与上一年年度（季度，月份）的对比. 比如：2013 年8 月，A 市用电量同比增加r%，指的是2013 年8 月，A 市用电量比2012 年8 月，A 市用电量增加了r% .', null, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 20, true, 87, null),
  ('eae05f8b-f76b-535b-b894-c97a6d65c049', '22222222-2222-2222-2222-222222222216', 'short', '环比是指本季度或者月度的对比. 比如：2013 年8 月，A 市用电量环比增加r%，指的是2013 年8 月，A 市用电量比2013 年7 月，A 市用电量增加了r% . 二、股票：总市值=每股股价×总股数 三、年龄问题（牢记年龄差不变） 例：今年为2013 年，女儿的年龄是母亲的 1 4，40 年后女儿的年龄是母亲年龄 的 2', null, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 20, true, 88, null),
