  ('411e52e0-b60c-534b-89a8-b93cde0f9f2b', '22222222-2222-2222-2222-22222222221a', 'short', '子集的个数：含有𝑛个元素的集合有2𝑛个子集，2𝑛−1个真子集，2𝑛−1个 非空子集，2𝑛−2个非空真子集. 例如：集合{1,2,3}有子集∅,{1}，{2}，{3}，{1,2}，{1,3}，{2,3}，{1,2,3}.', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 1, null),
  ('8df954c8-0fae-5139-a979-ad2e6131738a', '22222222-2222-2222-2222-22222222221a', 'short', '点(𝑥0, 𝑦0)到直线𝑎𝑥+ 𝑏𝑦+ 𝑐= 0的距离𝑑= |𝑎𝑥0+𝑏𝑦0+𝑐| √𝑎2+𝑏2 .', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 2, null),
  ('e4497d9d-21f8-5684-b4a5-53245b0be7df', '22222222-2222-2222-2222-22222222221a', 'short', '直线𝑎𝑥+ 𝑏𝑦+ 𝑐1 = 0与直线𝑎𝑥+ 𝑏𝑦+ 𝑐2 = 0的距离𝑑= |𝑐1−𝑐2| √𝑎2+𝑏2.', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 3, null),
  ('6cbd0002-923f-5a9e-8666-668f6159fe42', '22222222-2222-2222-2222-22222222221a', 'short', '长方体，体对角线𝐴′𝐶：𝑑= √𝑎2 + 𝑏2 + 𝑐2.', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 4, null),
