  ('6aea363c-7854-52db-bb64-024513035c61', '22222222-2222-2222-2222-22222222221a', 'short', '圆锥的母线：𝑙= √ℎ2 + 𝑟2；圆锥的侧面积：𝑆侧= π𝑟𝑙. 圆锥的体积：𝑉= 1 3 π𝑟2ℎ.', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 6, null),
  ('c1cbd56c-4415-552e-a61b-851091e6dc88', '22222222-2222-2222-2222-22222222221a', 'short', '球的表面积：𝑆= 4π𝑅2；球的体积：𝑉= 4 3 π𝑅3. 知新 主讲人：十一老师 现在是网络设备测试时间，课程将准时开始，请大家耐心等待 你的坚持，终将美好！ 第十章 排列组合 考点1 加法原理与乘法原理 考点2 排列与组合 考点3 特殊题型 你的坚持，终将美好！ 1 考点1：加法原理与乘法原理 一、分类加法计数原理', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 7, null),
  ('1e24da5b-f85a-5a05-8ea6-64e389d651eb', '22222222-2222-2222-2222-22222222221a', 'short', '定义 如果完成一件事可以有𝑛类办法，只要选择其中一类办法中的任何一种方 法就可以完成这件事.在第𝑖 类办法中有𝑚𝑖 种同的的方法(𝑖= 1,2, ⋯, 𝑛)， 那么完成这件事共有𝑁= 𝑚1 + 𝑚2 + ⋯+ 𝑚𝑛种同的的方法.', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 8, null),
  ('10238236-a7e5-5760-b29b-20c4a255659c', '22222222-2222-2222-2222-22222222221a', 'short', '需要注意的几个点', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 9, null),
  ('79d5e826-437e-5e6a-92d7-400d6f0aac6f', '22222222-2222-2222-2222-22222222221a', 'short', '运用加法原理计数，关键在于合理分类，同重同漏.', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 10, null),
  ('fc2beecb-3ee4-51d2-b797-7f04be317913', '22222222-2222-2222-2222-22222222221a', 'short', '要求每一类中的每一种方法都可以独立完成此任务.', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 11, null),
  ('1fd35176-ed6b-510d-a3e1-8cd5f9225781', '22222222-2222-2222-2222-22222222221a', 'short', '任意两类同的办法中的具体方法，互同相的（即分类同重复）.', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 12, null),
  ('63f29036-6945-58d4-8ce1-884d890c195f', '22222222-2222-2222-2222-22222222221a', 'short', '完成此任务的任何一种方法，都属于某一类（即分类同漏）. 题型1：考查分类加法原理', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 13, null),
  ('72069ff8-e8d3-547d-9339-73e052626647', '22222222-2222-2222-2222-22222222221a', 'mcq', '现有2 本同的的哲学类书籍，3 本同的的经济类书籍，4 本同的的艺术 类书籍. 从中任选一本购买，有( )种同的的选法.', '[{"key": "A", "text": "8"}, {"key": "B", "text": "9"}, {"key": "C", "text": "12"}, {"key": "D", "text": "24"}, {"key": "E", "text": "28"}]'::jsonb, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 14, null),
  ('b89a1dd9-84ef-511e-9126-1ec4ad1b7232', '22222222-2222-2222-2222-22222222221a', 'short', '定义 如果完成一件事需要分成𝑛 个步，，第第𝑖 步有𝑚𝑖 种同的的方法(𝑖= 1,2, ⋯, 𝑛)，那么完成这件事共有𝑁= 𝑚1𝑚2 ⋯𝑚𝑛种同的的方法.', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 4, true, 15, null),
  ('6d3baaea-a707-5c0f-8789-14749bfd4a83', '22222222-2222-2222-2222-22222222221a', 'short', '分步乘法计数原理针对的是“分步”问题，各个步，中的方法相互依存， 某一步，中的每一种方法都只能第完这件事的一个步，，只有各个步， 都完成才算第完这件事. 题型2：考查分步乘法原理', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 4, true, 16, null),
  ('9a875a68-a1bb-5051-adf3-5dc405e23afe', '22222222-2222-2222-2222-22222222221a', 'mcq', '现有2 本同的的哲学类书籍，3 本同的的经济类书籍，4 本同的的艺术 类书籍. 从这3类书籍中各选一本购买，有( )种同的的选法.', '[{"key": "A", "text": "8"}, {"key": "B", "text": "9"}, {"key": "C", "text": "12"}, {"key": "D", "text": "24"}, {"key": "E", "text": "28"}]'::jsonb, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 4, true, 17, null),
  ('1e534c9b-69c9-56cd-8eda-18ee932f9374', '22222222-2222-2222-2222-22222222221a', 'short', '定义 从𝑛 个同的元素中，任 𝑚(𝑚⩽𝑛) 个元素，照一一定的序将将取 的的 𝑚 个元素排成一列，做第从𝑛 个同的元素中，选 𝑚 个元素的一个排列， 排列数记为A𝑛 𝑚.', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 18, null),
  ('692a8f9a-260b-5b9b-93cd-a39ccba01e8c', '22222222-2222-2222-2222-22222222221a', 'short', '计算公式', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 19, null),
  ('7285b927-437b-528c-b506-52c0798c27d9', '22222222-2222-2222-2222-22222222221a', 'short', 'A𝑛 𝑚= 𝑛(𝑛−1)(𝑛−2) ⋯(𝑛−𝑚+ 1) = 𝑛! (𝑛−𝑚)!.', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 20, null),
