  ('4f787079-8359-5df6-a76b-9749f0163c11', '22222222-2222-2222-2222-22222222221a', 'short', '定义 从𝑛个同的元素中，任 𝑚(𝑚⩽𝑛)个元素并成一组，称为从𝑛个同的元素 中 的𝑚个元素的一个组合，组合数记为C𝑛 𝑚.', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 30, null),
  ('e5a3e990-11f4-5fae-b6a9-8ef729ef149b', '22222222-2222-2222-2222-22222222221a', 'short', '公式与性质', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 31, null),
  ('87763060-1213-5832-a904-d4bcd5ca06ac', '22222222-2222-2222-2222-22222222221a', 'short', 'C𝑛 𝑚= A𝑛𝑚 𝑚! = 𝑛! 𝑚!(𝑛−𝑚)! = 𝑛(𝑛−1)(𝑛−2)⋯(𝑛−𝑚+1) 𝑚(𝑚−1)⋯2∙1 . 例：C6 3 = 6! 3!(6−3)! = 6×5×4 3×2×1 = 20.', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 32, null),
  ('2d801345-703c-585b-9d07-a2541390dc50', '22222222-2222-2222-2222-22222222221a', 'short', 'C𝑛 𝑚= C𝑛 𝑛−𝑚；C𝑛 𝑚= C𝑛−1 𝑚−1 + C𝑛−1 𝑚. 例：从𝐴, 𝐵, 𝐶, 𝐷, 𝐸中选2 个人参加活动，有C5 2种. 我们也可以，以是否选𝐴来分类： ①选𝐴，还需要从剩下4 个人中选1 个人，有C4 1种， ②同选𝐴，需要从剩下4 个人中选2 个人，有C4 2种， ③总数为：C4 1 + C4', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 33, null),
  ('c6f718e5-d894-5c94-b776-f69f7d83e5c3', '22222222-2222-2222-2222-22222222221a', 'short', '有C5 2 = C4 1 + C4', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 34, null),
  ('3046a17b-c3f7-5fa7-bacd-1aeaa4df7b51', '22222222-2222-2222-2222-22222222221a', 'short', '结论得以验证.', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 35, null),
  ('9419e275-12a3-5668-a164-0f3e65b1b0af', '22222222-2222-2222-2222-22222222221a', 'short', 'C𝑛 0 + C𝑛 1 + ⋯+ C𝑛 𝑛= 2𝑛. 假设有 𝑛个同的的物品，从中选的一个子集（包括空集和全集）有多 少种选法？', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 36, null),
  ('4b0fe48f-88e5-5202-87a8-e3f15169be4e', '22222222-2222-2222-2222-22222222221a', 'short', 'C3 2 = C3 1 = 3，C4 2 = 6，C5 2 = C5 3 = 10，C6 2 = C6 4 = 15，C6 3 = 20， C7 2 = C7 5 = 21. 你的坚持，终将美好！ 7 题型2：考查组合数的应用', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 37, null),
  ('b87945c0-478d-5d4e-b493-7189e571c189', '22222222-2222-2222-2222-22222222221a', 'mcq', '某商店经营15 种商品，每次在橱窗内陈列5 种.若每两次陈列的商品 同完全相的，则最多可陈列( )次.', '[{"key": "A", "text": "3000"}, {"key": "B", "text": "3003"}, {"key": "C", "text": "4000"}, {"key": "D", "text": "4003"}, {"key": "E", "text": "4300"}]'::jsonb, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 9, true, 38, null),
