  ('fe2a4ff0-9d51-5af9-87f8-899f4e4897c7', '22222222-2222-2222-2222-22222222221a', 'short', '规律 你的坚持，终将美好！ 19', null, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 20, true, 61, null),
  ('1f6c0f2b-431c-5052-9797-7e428fe9bf65', '22222222-2222-2222-2222-22222222221a', 'mcq', '三位教师分配到6 个班级任教，若其中一人教一个班、一个人教两个 班、一个人教三个班，则共有分配方法( )种.', '[{"key": "A", "text": "720"}, {"key": "B", "text": "360"}, {"key": "C", "text": "120"}, {"key": "D", "text": "60"}, {"key": "E", "text": "30"}]'::jsonb, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, true, 62, null),
  ('52f8ab5a-e7a5-51e2-b167-51ce69de7b62', '22222222-2222-2222-2222-22222222221a', 'mcq', '某大学派的5 名志愿者到西部4 取中学支教，若每取中学至少有一名 志愿者，则同的的分配方案共有( )种.', '[{"key": "A", "text": "240"}, {"key": "B", "text": "144"}, {"key": "C", "text": "120"}, {"key": "D", "text": "60"}, {"key": "E", "text": "24"}]'::jsonb, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, true, 63, null),
  ('c43876a1-18e4-5e55-9d69-3a6541832871', '22222222-2222-2222-2222-22222222221b', 'short', 'A𝑛 𝑚= 𝑛(𝑛−1)(𝑛−2) ⋯(𝑛−𝑚+ 1) = 𝑛! (𝑛−𝑚)!.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 1, null),
  ('4f5c324f-615c-57c5-bfd5-9a2a28f695d6', '22222222-2222-2222-2222-22222222221b', 'short', '0! = 1，2! = 2，3! = 6，4! = 24，5! = 120.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 2, null),
  ('99c03623-4d19-57ff-be24-adb27f45f075', '22222222-2222-2222-2222-22222222221b', 'short', 'C𝑛 𝑚= A𝑛𝑚 𝑚! = 𝑛! 𝑚!(𝑛−𝑚)! = 𝑛(𝑛−1)(𝑛−2)⋯(𝑛−𝑚+1) 𝑚(𝑚−1)⋯2∙1 .', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 3, null),
  ('508e3b04-c2a2-5b5e-9e08-c6fcf5e6fe66', '22222222-2222-2222-2222-22222222221b', 'short', 'C3 2 = C3 1 = 3，C4 2 = 6，C5 2 = C5 3 = 10，C6 2 = C6 4 = 15，C6 3 = 20. 知新 主讲人：十一老师 现在是网络设备测试时间，课程将准时开始，请大家耐心等待 你的坚持，终将美好！ 15 九、定序问题：题目出现整体排列，部分元素顺序固定. 当把𝑛个元素进行排序的时候，其中𝑚个元素不计顺序或者顺序已定，要把 这𝑚个元素的顺序除掉，有多少除多少. 公式= 总排列数 所有定序组的阶乘乘积（只能在“所有被定序的位置地位完全平等，没有 额外限制”时使用）', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 4, null),
  ('cb252c78-ad6d-57f8-a051-92e83a7622b0', '22222222-2222-2222-2222-22222222221b', 'short', '算总排列数：先按无任何顺序约束，计算所有元素的全排列数；', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 2, true, 5, null),
  ('a693000f-6474-573d-97f6-f8245fda8ef1', '22222222-2222-2222-2222-22222222221b', 'short', '识别定序组：找出所有内部顺序被强制固定的元素组；', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 2, true, 6, null),
  ('213965c2-086a-5f32-974f-9f69d3eac916', '22222222-2222-2222-2222-22222222221b', 'short', '除以阶乘去重：对每个定序组，除以其元素个数的阶乘 （为固固定顺序 的元素，原本有𝑘!种排列，现在只保留 1 种，所以要除以𝑘! ）.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 2, true, 7, null),
  ('e4c42403-f0dc-5706-9429-a7ae4297e076', '22222222-2222-2222-2222-22222222221b', 'mcq', '某班举办新年联欢会，原定的5 个节目已排成节目单，开演前又增加 了两个新节目，如果将这两个新节目插入原节目当中，那么有( )种 不同的方法.', '[{"key": "A", "text": "15"}, {"key": "B", "text": "20"}, {"key": "C", "text": "21"}, {"key": "D", "text": "30"}, {"key": "E", "text": "42"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 2, true, 8, null),
  ('5043ec32-0863-5f90-af01-4dbbf716c273', '22222222-2222-2222-2222-22222222221b', 'short', '先对元素进行全排列，再除以定序元素的全排列.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 9, null),
  ('33f96251-4937-580b-8eca-1363a4c3e911', '22222222-2222-2222-2222-22222222221b', 'short', '先在总位置中选出定序元素的位置（固定顺序的元素放入其中），然后其余元素在 剩下的位置中全排列.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 10, null),
  ('0c524b05-095e-5df7-a918-5655e380512d', '22222222-2222-2222-2222-22222222221b', 'mcq', '用0,1,2,3,4,5 组成没有重复数字的四位数，其中千位数字大于百位数 字且百位数字大于十位数字的四位数个数是( ).', '[{"key": "A", "text": "36"}, {"key": "B", "text": "40"}, {"key": "C", "text": "48"}, {"key": "D", "text": "60"}, {"key": "E", "text": "72"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 11, null),
  ('eb83ff1d-ebd4-5cc5-8433-5925753194d5', '22222222-2222-2222-2222-22222222221b', 'mcq', '如图𝐴, 𝐵, 𝐶, 𝐷，4 个区域，用5 种不同颜色将其染色，要求相邻两个 区域使用不同颜色，𝐴和𝐷区域使用不同颜色，则染色方法共有( )种.', '[{"key": "A", "text": "260"}, {"key": "B", "text": "210"}, {"key": "C", "text": "120"}, {"key": "D", "text": "320"}, {"key": "E", "text": "240"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 6, true, 12, null),
  ('37644375-0ea9-592c-9e03-9fa93d5f7c33', '22222222-2222-2222-2222-22222222221b', 'short', '将3 份不同的书分给3 位同学，一人一堆. A3 3种', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 7, true, 13, null),
  ('7bf5356a-1b6a-5f90-94a0-82b2d0482cea', '22222222-2222-2222-2222-22222222221b', 'short', '将6 本不同的书平均分给3 位同学（𝐴, 𝐵, 𝐶）. C6 2C4 2C2 2种 ①从6 本不同的书中取2 本给𝐴，有C6 2种. ②从剩余4 本不同的书中取2 本给𝐵，有C4 2种. ③将最后2 本书给𝐶，有C2 2种. 思考一下这个分配过程： 第一步：将6 本不同的书平均分成3 份，假设𝑥种情况. 第二步：将这3 份书分发给3 位同学，一人一份. 有A3 3种. 则有：C6 2C4 2C2 2 = 𝑥∙A3 3 ⇒ 𝑥= C6 2C4 2C2 2 A3 3', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 7, true, 14, null),
  ('b20de8c7-99b4-5d62-976d-cf690dd3a987', '22222222-2222-2222-2222-22222222221b', 'short', '将6 本不同的书平均分成3 份. C6 2C4 2C2 2 A3 3 种 你的坚持，终将美好！ 21 二、环形排列：题目中出现环形（圆形）排列.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 7, true, 15, null),
  ('03876816-63f4-5110-86a8-0e8d739487e3', '22222222-2222-2222-2222-22222222221b', 'short', '𝑛个不同元素作圆形排列，共有(𝑛−1)!种排法.（重点在确定头位） 环形每个位置都一样，所以需要除序， 𝑛! 𝑛= (𝑛−1)!.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 16, null),
  ('e8a35c62-4a0d-5764-bcc3-0f5e7b7cc3ac', '22222222-2222-2222-2222-22222222221b', 'short', '如果从𝑛个不同元素中取出𝑚个元素作圆形排列共有 A𝑛𝑚 𝑚种排法.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 17, null),
  ('f5699f96-a50f-559b-8d3a-76c612a0979d', '22222222-2222-2222-2222-22222222221b', 'short', '𝐴𝐵𝐶𝐷𝐸五个人坐一个圆桌，有几种坐法？ 定一个人，1 × 4 × 3 × 2 × 1 = 4! = 24.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 18, null),
  ('fb3ec0f9-eea7-5f26-9c90-c1d301568644', '22222222-2222-2222-2222-22222222221b', 'short', '𝐴𝐵𝐶𝐷𝐸五个人坐一个圆桌，𝐴和𝐵不能相邻，有几种坐法？ 定一个人𝐴，则𝐵的有2 种放法，剩下三个人全排列，1 × 2 × 3！= 12种. 反面思想：𝐴𝐵捆绑有2!种方法，变成4 个元素排列，则他们环形排列有 3！种，总计4! −2 × 3！= 12种. 你的坚持，终将美好！ 22', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 19, null),
  ('35d8cf39-0df7-5bee-bd60-db7b7a2b4831', '22222222-2222-2222-2222-22222222221b', 'short', '𝐴𝐵𝐶𝐷𝐸五个人坐一个圆桌，𝐴和𝐵不能相邻，𝐵和𝐶不能相邻，有几种 坐法？ 定一个人𝐴，则𝐵的有2 种放法，𝐶有1 种方法，最后的两个人全排列 1 × 2 × 1 × 2！= 4种.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 9, true, 20, null),
  ('3a6730a4-01cd-57b7-a773-8c48107ba0ab', '22222222-2222-2222-2222-22222222221b', 'short', '𝐴𝐵𝐶𝐷𝐸五个人坐一个圆桌，𝐴𝐵𝐶三人中任意两人不能相邻，有几种坐 法？ 不存在这种情况，0 种. 你的坚持，终将美好！ 23 你的坚持，终将美好！ 第十一章 概率 考点1 古典概率模型 考点2 独立事件 考点3 伯努利概率模型 你的坚持，终将美好！ 1 序：基本概念', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 9, true, 21, null),
  ('1f1998d8-df5d-502d-a6d7-dc24c262d21a', '22222222-2222-2222-2222-22222222221b', 'short', '随机试验 若满足条件', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 12, true, 22, null),
  ('a11aa40c-1a34-5367-bf8b-1433977209ee', '22222222-2222-2222-2222-22222222221b', 'short', '试验可在相同条件下重复进行；', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 12, true, 23, null),
  ('82392e77-69bf-55bc-adac-7a3b89bfc4ad', '22222222-2222-2222-2222-22222222221b', 'short', '试验的结果具有很多可能性；', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 12, true, 24, null),
  ('90114f69-b0d1-5aab-84ce-9949ea11478b', '22222222-2222-2222-2222-22222222221b', 'short', '试验前不能确切知道会出现何种结果，只知道所有可能出现的结果. 这样的试验叫做随机试验，简称试验，记固𝐸.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 12, true, 25, null),
  ('03173781-8f7a-5a05-94d7-4e07036daf7c', '22222222-2222-2222-2222-22222222221b', 'short', '样本点与样本空间 把随机试验𝐸的每个可能的基本结果称固样本点，全体样本点的集合称固 试验𝐸的样本空间.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 12, true, 26, null),
  ('8cc3061d-f86b-5ac6-9c62-e9fb4bea865d', '22222222-2222-2222-2222-22222222221b', 'short', '随机事件 随机试验中的每个随机事件都可以用这个试验的样本空间的子集来表 示．我们将样本空间𝛺的子集称固随机事件，简称事件，并把只包含一个 样本点的事件称固基本事件，常用大写字母𝐴, 𝐵, 𝐶⋯表示.在每次试验中， 当且仅当𝐴中某个样本点出现时，称固事件𝐴发生.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 12, true, 27, null),
  ('cb4b11a9-c7f6-5c16-a263-90a21b0bb741', '22222222-2222-2222-2222-22222222221b', 'short', '必然事件：在试验中必然出现的事件，记作𝛺.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 12, true, 28, null),
  ('22377aaa-4ede-580b-b0ff-7c5bcd72b56f', '22222222-2222-2222-2222-22222222221b', 'short', '不可能事件：在试验中不可能出现的事件，记作∅. 你的坚持，终将美好！ 2 例：掷一颗骰子的样本空间固𝛺= {1,2,3,4,5,6}. 事件𝐴=“出现1 点”，它由𝛺的单个样本点“1”组成. 事件𝐵=“出现偶数点”，它由𝛺的三个样本点“2,4,6”组成. 事件𝐶=“出现的点数小于7”，它由𝛺的全部样本点“1,2,3,4,5,6”组成. 即必然事件𝛺. 事件𝐷= “出现的点数大于6”，𝛺中的任一样本点都不在𝐷中，所以𝐷是空 集，即不可能事件∅.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 12, true, 29, null),
  ('a4a745e5-dd44-553c-8b71-422db624c359', '22222222-2222-2222-2222-22222222221b', 'short', '随机事件的概率', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 13, true, 30, null),
  ('21b603b6-a713-5536-9110-7b70cd0788f1', '22222222-2222-2222-2222-22222222221b', 'short', '概率的定义 随机事件𝐴发生的可能性大小度量值称固事件𝐴的概率，记固𝑃(𝐴).', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 13, true, 31, null),
  ('92b72834-64b8-578d-9582-86bea0079292', '22222222-2222-2222-2222-22222222221b', 'short', '必然事件的概率：𝑃(𝛺) = 1.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 13, true, 32, null),
  ('1c019b79-ad6b-571c-b43f-785c385a9987', '22222222-2222-2222-2222-22222222221b', 'short', '不可能事件的概率：𝑃(∅) =0.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 13, true, 33, null),
  ('51061619-a834-590c-963c-47dc755e4828', '22222222-2222-2222-2222-22222222221b', 'short', '随机事件𝐴：0 ⩽𝑃(𝐴) ⩽1. 你的坚持，终将美好！ 3 考点1：古典概率模型 一、特征', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 13, true, 34, null),
  ('56870ae2-23ed-5a43-ae3e-6f0e6c6f8d23', '22222222-2222-2222-2222-22222222221b', 'short', '试验中所有可能出现的基本事件只有有限个；', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 14, true, 35, null),
  ('99e973d1-1737-51db-9778-088811d3a4a3', '22222222-2222-2222-2222-22222222221b', 'short', '每个基本事件出现的可能性是相等的. 具有这两个特点的概率模型称固古典概型（注意“等可能”这个特征）. 二、公式 如果随机事件𝐴包含的基本事件个数固𝑚，基本事件的总数固𝑛，则 𝑃(𝐴) = 𝐴包含的基本事件的个数 基本事件的总数 = 𝑚 𝑛. 三、取样问题（无特别说明情况下，取球问题一般把球看做不同元素）', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 14, true, 36, null),
  ('7a013c04-1f17-5e03-87e8-8080bfca8f9e', '22222222-2222-2222-2222-22222222221b', 'short', '有放回取样 从一个袋中取球，每次随机地取一只，每次取一只球后放回袋中，搅匀后 再取一球，这种取球方式固放回取样。放回抽样的每次抽样过程中每个 小球被抽到的几率是相等的.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 14, true, 37, null),
  ('47857977-a3db-5a55-abeb-9ff16becb0e5', '22222222-2222-2222-2222-22222222221b', 'short', '无放回抽样 从一个袋中取球，每次取一只球后不放回袋中，下一次从剩余的球中再 取一球，这种取球方式固不放回取样.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 14, true, 38, null),
  ('5dc4016d-c25e-5040-973b-902aa3fb5682', '22222222-2222-2222-2222-22222222221b', 'short', '抽签原理 口袋中有𝑎个红球，𝑏个白球，从中把球一个个取出(不放回/有放回)， 则第𝑘次取到的是红球的概率是 𝑎 𝑎+𝑏，第𝑘次取到的是白球的概率是 𝑏 𝑎+𝑏. 你的坚持，终将美好！ 4 小试牛刀 例：一个口袋内有7 个白球和3 个黑球，分别求下列事件的概率.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 14, true, 39, null),
  ('357166ce-ebca-5352-bba2-bf69701fdbfb', '22222222-2222-2222-2222-22222222221b', 'short', '事件𝐴：从中摸出一个放回后再摸一个，两次摸出的球是一白一黑.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 15, true, 40, null),
  ('b2134381-041e-528d-a104-57a62cf3d312', '22222222-2222-2222-2222-22222222221b', 'short', '42）', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 15, true, 41, null),
  ('3d2ba2ad-c407-5081-a190-7f9438be7ba7', '22222222-2222-2222-2222-22222222221b', 'short', '事件𝐵：从袋中摸出一个黑球，放回后再摸出一个白球.（0.21）', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 15, true, 42, null),
  ('ab2f71e5-14fd-56d5-92a4-07968a0f0730', '22222222-2222-2222-2222-22222222221b', 'short', '事件𝐶：从袋中摸出两个球，一个黑球，一个白球.（ 7 15）', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 15, true, 43, null),
  ('c1d048ba-2532-5ac8-b4ec-1048b944463a', '22222222-2222-2222-2222-22222222221b', 'short', '事件𝐷：从袋中依次摸出两个球，一个黑球，一个白球.（ 7 15） 【注】“先后无放回地取𝒌个球”与“任取𝒌个球”的概率相同，由于任取的计算更方 便，所以计算前者可按后者来计算. 你的坚持，终将美好！ 5 题型1：考查取球问题', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 15, true, 44, null),
  ('413c8a72-e3d8-5a91-8374-de4565f339a9', '22222222-2222-2222-2222-22222222221b', 'mcq', '盒中有5 只质地、大小完全相同的球，其中纯红球、纯黑球、纯白球 各有1 只，同时印有红、黑、白三种颜色的三色球有2 只，现从中任 取2 球，其中恰有一球带有红色的概率固( ).', '[{"key": "A", "text": "1 6"}, {"key": "B", "text": "1 3"}, {"key": "C", "text": "1 2"}, {"key": "D", "text": "3 5"}, {"key": "E", "text": "5 6"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, true, 45, null),
  ('a72e6818-0d25-51ab-80dd-b11f178a1beb', '22222222-2222-2222-2222-22222222221b', 'mcq', '一只口袋中有5 只同样大小的球，编号分别固1，2，3，4，5，今从 中随机抽取3 只球，则取到的球中最大号码是4 的概率固( ).', '[{"key": "A", "text": "0.3"}, {"key": "B", "text": "0.4"}, {"key": "C", "text": "0.5"}, {"key": "D", "text": "0.6"}, {"key": "E", "text": "0.7"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, true, 46, null),
  ('3c7413b8-518d-5158-afeb-d3229bdc3aff', '22222222-2222-2222-2222-22222222221b', 'mcq', '某剧院歌剧有三类票价：前座 50 元、中座 35 元、后座 20 元。每次购 票时，买到前、中、后座票的概率相等，两次购票相互独立。现随机购 买2 张票，则两张票总票价不超过70 元的概率固( ).', '[{"key": "A", "text": "1 3"}, {"key": "B", "text": "1 2"}, {"key": "C", "text": "3 5"}, {"key": "D", "text": "2 3"}, {"key": "E", "text": "2 5 题型3：考查相同取样问题"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 18, true, 47, null),
  ('059e6ffe-244c-5aa4-a61b-e827e1d4c3c2', '22222222-2222-2222-2222-22222222221b', 'mcq', '某商店举行店庆活动，顾客消费达到一定金额后，可以在4 种赠品中 随机选取2 件不同的赠品，在任意两位顾客所选的赠品中，恰有1 件 品种相同的概率是( ).', '[{"key": "A", "text": "1 6"}, {"key": "B", "text": "1 4"}, {"key": "C", "text": "1 3"}, {"key": "D", "text": "1 2"}, {"key": "E", "text": "2 3 你的坚持，终将美好！ 8 你的坚持，终将美好！ 9 你的坚持，终将美好！ 10 题型4：考查正难则反"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 18, true, 48, null),
  ('03cd5cdb-60f6-5065-880e-d3943326e8f9', '22222222-2222-2222-2222-22222222221b', 'mcq', '已知10 件产品中有4 件一等品，从中任取2 件，则至少有1 件一等品 的概率固( ).', '[{"key": "A", "text": "1 3"}, {"key": "B", "text": "2 3"}, {"key": "C", "text": "2 15"}, {"key": "D", "text": "8 15"}, {"key": "E", "text": "13 15 题型5：考查分房问题"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, true, 49, null),
  ('64104630-3db2-50f6-84e0-3e680e6d8a96', '22222222-2222-2222-2222-22222222221b', 'mcq', '将2 个红球与1 个白球随机地放入甲、乙、丙三个盒子中，则乙盒中 至少有1 个红球的概率固( ).', '[{"key": "A", "text": "1 9"}, {"key": "B", "text": "8 27"}, {"key": "C", "text": "4 9"}, {"key": "D", "text": "5 9"}, {"key": "E", "text": "17 27 你的坚持，终将美好！ 11 你的坚持，终将美好！ 12 题型6：考查分组问题"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, true, 50, null),
  ('ffa487f1-2bb3-5a2e-9ff0-d37a18b993cf', '22222222-2222-2222-2222-22222222221b', 'mcq', '10 名网球选手中有2 名种子选手.现将他们分成两组，每组5 人，则2 名种子选手不在同一组的概率固( ).', '[{"key": "A", "text": "5 18"}, {"key": "B", "text": "4 9"}, {"key": "C", "text": "5 9"}, {"key": "D", "text": "1 2"}, {"key": "E", "text": "2 3 题型7：考查数字问题"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 23, true, 51, null),
  ('51eb53ae-ba08-5352-ab94-a52bf5b46c9c', '22222222-2222-2222-2222-22222222221b', 'mcq', '从0,1,2,3 这四个数字中任取3 个进行排列，组成无重复数字的三位数， 则排成的三位数是偶数的概率固( ).', '[{"key": "A", "text": "7 36"}, {"key": "B", "text": "2 9"}, {"key": "C", "text": "1 4"}, {"key": "D", "text": "5 9"}, {"key": "E", "text": "11 36 你的坚持，终将美好！ 13 你的坚持，终将美好！ 14 考点2：独立事件 一、事件的关系"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 23, true, 52, null),
  ('afc761e8-8965-5c7d-b085-6fe60e38d786', '22222222-2222-2222-2222-22222222221b', 'short', '𝐴+ 𝐵：事件𝐴与事件𝐵的和事件，含义固𝐴,𝐵至少有一个发生.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 25, true, 53, null),
  ('6c8fe88d-9cb2-52d2-9cae-a5931feacbb1', '22222222-2222-2222-2222-22222222221b', 'short', '𝐴𝐵：事件𝐴与事件𝐵的积事件，含义固𝐴, 𝐵同时发生.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 25, true, 54, null),
  ('ce05af66-92d5-5498-a796-1d9a1532ec6e', '22222222-2222-2222-2222-22222222221b', 'short', '𝐴−𝐵= 𝐴𝐵̅ = 𝐴−𝐴𝐵： 事件𝐴与事件𝐵的差事件，含义固𝐴发生，𝐵不发生. 你的坚持，终将美好！ 15', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 25, true, 55, null),
  ('5d39632d-85f9-5d7d-8c6b-ca2189dd47ee', '22222222-2222-2222-2222-22222222221b', 'short', '𝐴̅：事件𝐴的对立事件，含义固𝐴不发生.', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 26, true, 56, null),
  ('2400129e-c1de-540d-a247-ce11f9b35476', '22222222-2222-2222-2222-22222222221b', 'short', '若𝐴∩𝐵= ∅（𝐴、𝐵不可能同时发生），则𝐴、𝐵互斥，也叫互不相容. 二、独立事件概念 如果两个事件中任一事件的发生不影响另一事件的概率，则称这两个事件 是相互独立的. 三、独立事件定义 若𝑃(𝐴𝐵) = 𝑃(𝐴)𝑃(𝐵)，则称两个事件𝐴和𝐵是相互独立的. 即相互独立事件同时发生的概率等于每个事件发生的概率相乘. 你的坚持，终将美好！ 16 四、独立事件公式 若𝑃(𝐴𝐵) = 𝑃(𝐴)𝑃(𝐵)，则称两个事件𝐴和𝐵是相互独立的. 𝐴与𝐵是相互独立 ⇔𝐴与𝐵̅是相互独立 ⇔𝐴̅与𝐵是相互独立 ⇔𝐴̅与𝐵̅是相互独立 五、互斥事件', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 26, true, 57, null),
  ('5a276abf-acfc-52c3-8b50-6ccc6da63500', '22222222-2222-2222-2222-22222222221b', 'short', '𝐴、𝐵互斥⇔𝑃(𝐴𝐵) = 0 ⇔𝐴、𝐵不能同时发生 ⇔𝑃(𝐴+ 𝐵) = 𝑃(𝐴) + 𝑃(𝐵) 【注】𝐴𝐵与𝐴−𝐵互斥，故有𝑃(𝐴𝐵+ 𝐴−𝐵) = 𝑃(𝐴𝐵) + 𝑃(𝐴−𝐵)， 又𝐴𝐵+ 𝐴−𝐵= 𝐴，则𝑃(𝐴) = 𝑃(𝐴𝐵) + 𝑃(𝐴−𝐵)， 移项得𝑃(𝐴−𝐵) = 𝑃(𝐴) −𝑃(𝐴𝐵)，或𝑃(𝐴𝐵̅) = 𝑃(𝐴) −𝑃(𝐴𝐵). 六、区分 你的坚持，终将美好！ 17 题型1：考查穷举法', null, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 27, true, 58, null),
  ('a928292c-d2f0-54e1-96e4-b263ef501ed9', '22222222-2222-2222-2222-22222222221b', 'mcq', '掷一枚均匀的硬币若干次，当正面向上次数大于反面向上次数时停止， 则在4 次之内停止的概率固( ).', '[{"key": "A", "text": "1 8"}, {"key": "B", "text": "3 8"}, {"key": "C", "text": "5 8"}, {"key": "D", "text": "3 16"}, {"key": "E", "text": "5 16 题型2：考查正难则反"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 28, true, 59, null),
  ('eb73bcb3-a046-50e8-b62f-71165395fbc9', '22222222-2222-2222-2222-22222222221b', 'mcq', '如图，由𝑃到𝑄的电路中有三个元件，分别标固𝑇1，𝑇2，𝑇3. 电流能通过 𝑇1，𝑇2，𝑇3的概率分别固0.9，0.9，0.99.假设电流能否通过三个元件是 相互独立的，则电流能在𝑃，𝑄之间通过的概率是( ).', '[{"key": "A", "text": "0.8019"}, {"key": "B", "text": "0.9989"}, {"key": "C", "text": "0.999"}, {"key": "D", "text": "0.9999"}, {"key": "E", "text": "0.99999"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 28, true, 60, null),
  ('07fed0d1-4a09-5f94-9cf5-bd7685569f7d', '22222222-2222-2222-2222-22222222221c', 'short', 'A𝑛 𝑚= 𝑛(𝑛−1)(𝑛−2) ⋯(𝑛−𝑚+ 1) = 𝑛! (𝑛−𝑚)!.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 1, null),
  ('f7d44b2c-d606-5f81-b6d6-9b86465462a1', '22222222-2222-2222-2222-22222222221c', 'short', '0! = 1，2! = 2，3! = 6，4! = 24，5! = 120.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 2, null),
  ('18904463-7e48-5823-9676-99d2022b464a', '22222222-2222-2222-2222-22222222221c', 'short', 'C𝑛 𝑚= A𝑛𝑚 𝑚! = 𝑛! 𝑚!(𝑛−𝑚)! = 𝑛(𝑛−1)(𝑛−2)⋯(𝑛−𝑚+1) 𝑚(𝑚−1)⋯2∙1 .', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 3, null),
  ('ea1e099e-0666-59ea-b0bd-181ba7ed66f9', '22222222-2222-2222-2222-22222222221c', 'short', 'C3 2 = C3 1 = 3，C4 2 = 6，C5 2 = C5 3 = 10，C6 2 = C6 4 = 15，C6 3 = 20.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 4, null),
  ('b5929f5f-2b39-5592-b165-39d8e8cf650c', '22222222-2222-2222-2222-22222222221c', 'short', '若𝑃(𝐴𝐵) = 𝑃(𝐴)𝑃(𝐵)，则称两个事件𝐴和𝐵是相互独立的.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 5, null),
  ('651aeb44-2393-508a-ab45-cb4426ff720f', '22222222-2222-2222-2222-22222222221c', 'short', '𝐴、𝐵互斥⇔𝑃(𝐴𝐵) = 0. 知新 主讲人：十一老师 现在是网络设备测试时间，课程将准时开始，请大家耐心等待 你的坚持，终将美好！ 13', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 6, null),
  ('95729075-9a84-5943-ac45-88549b342660', '22222222-2222-2222-2222-22222222221c', 'short', '甲、乙、丙三台机床各自独立地加工同一种零件，已知甲机床加工的零 件是一等品而乙机床加工的零件不是一等品的概率为 1 4，乙机床加工的 零件是一等品而丙机床加工的零件不是一等品的概率为 1 12 ，甲、丙两 台机床加工的零件都是一等品的概率为 2', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 2, true, 7, null),
  ('bcddab54-95de-592a-91a4-94e284ed52a3', '22222222-2222-2222-2222-22222222221c', 'mcq', '从甲、乙、丙加工的零件中 各取一个检验，求至少有一个一等品的概率( ).', '[{"key": "A", "text": "7 36"}, {"key": "B", "text": "2 9"}, {"key": "C", "text": "1 4"}, {"key": "D", "text": "5 9"}, {"key": "E", "text": "5 6 你的坚持，终将美好！ 14 你的坚持，终将美好！ 15 考点3：伯努利概率模型 一、独立重复试验 在相同条件下，将某试验重复进行𝑛次，且每次试验中任何一事件的概率不 受其它次试验结果的影响，此种试验称为𝑛次独立重复试验. 注意以下几点："}]'::jsonb, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 2, true, 8, null),
  ('acfc7efc-c0e7-5e39-80bd-17994d2f5d99', '22222222-2222-2222-2222-22222222221c', 'short', '试验的次数不止一次，而是多次，次数𝑛⩾1.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 4, true, 9, null),
  ('bb2f2d69-7384-5df6-904c-ec617b81e1af', '22222222-2222-2222-2222-22222222221c', 'short', '每次试验的条件是一样的，是重复性的试验序列.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 4, true, 10, null),
  ('44d0fafb-7d9b-525c-a6e0-7b556e608485', '22222222-2222-2222-2222-22222222221c', 'short', '每次试验的结果只有𝐴与𝐴̅两种（即事件𝐴要么发生，要么不发生）， 每次试验相互独立，试验的结果互不影响，即各次试验中发生的概率 保持不变. 二、伯努利公式 如果在1 次试验中，某事件发生的概率是𝑝，那么在𝑛次独立重复试验中这 个事件恰好发生𝑘次的概率：𝑃𝑛(𝑘) = C𝑛 𝑘𝑝𝑘(1 −𝑝)𝑛−𝑘, (𝑘= 0,1,2, ⋯𝑛).', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 4, true, 11, null),
  ('46f69978-e6da-5632-8361-5742628b6dd2', '22222222-2222-2222-2222-22222222221c', 'short', '𝑘= 𝑛时，即在𝑛次独立重复试验中，事件全部发生，概率为𝑝𝑛.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 4, true, 12, null),
  ('e2c15970-e385-506a-b702-1d80965cb4ad', '22222222-2222-2222-2222-22222222221c', 'short', '𝑘= 0时，即在𝑛次独立重复试验中，事件没有发生，概率为(1 −𝑝)𝑛. 你的坚持，终将美好！ 16 题型1：考查伯努利概型', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 4, true, 13, null),
  ('7a24fb70-6bf2-5deb-9a9f-ffa13355996b', '22222222-2222-2222-2222-22222222221c', 'short', '掷一枚不均匀的硬币，正面朝上的概率为 2', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 14, null),
  ('c918303b-9fff-5ffa-9614-f0c7bc86b87e', '22222222-2222-2222-2222-22222222221c', 'mcq', '若将此硬币掷4 次，则正 面朝上3 次的概率是( ).', '[{"key": "A", "text": "1 81"}, {"key": "B", "text": "8 27"}, {"key": "C", "text": "32 81"}, {"key": "D", "text": "1 2"}, {"key": "E", "text": "26 27 要求判断每题给出的条件（1）和（2）能否充分支持题干所陈述的结论．以下五个选项为 判断结果，请选择一项符合试题要求的判断。"}, {"key": "A", "text": "条件（1）充分，但条件（2）不充分"}, {"key": "B", "text": "条件（2）充分，但条件（1）不充分"}, {"key": "C", "text": "条件（1）和（2）单独都不充分，但条件（1）和条件（2）联合起来充分"}, {"key": "D", "text": "条件（1）充分，条件（2）也充分"}, {"key": "E", "text": "条件（1）和条件（2）单独都不充分，条件（1）和条件（2）联合起来也不充分"}]'::jsonb, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 15, null),
  ('b834dee8-2457-5c3c-851e-29052c603a6b', '22222222-2222-2222-2222-22222222221c', 'short', '张三以卧姿射击10 次，命中靶子7 次的概率是 15 128.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 16, null),
  ('ba83ba15-1b9b-5bef-a61f-70ab01653201', '22222222-2222-2222-2222-22222222221c', 'short', '张三以卧姿打靶的命中率是0.2.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 17, null),
  ('ac45cedc-4490-578e-a959-4e2ef85cbae7', '22222222-2222-2222-2222-22222222221c', 'short', '张三以卧姿打靶的命中率是0.5. 你的坚持，终将美好！ 17 你的坚持，终将美好！ 18', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 18, null),
  ('48f0a042-ec80-5028-b457-63532cd72c75', '22222222-2222-2222-2222-22222222221c', 'mcq', '某乒乓球男子单打决赛在甲、乙两选手间进行，比赛采用7 局4 胜制. 已知每局比赛甲选手战胜乙选手的概率为0.7，则甲选手以4:1 战胜乙 选手的概率为( ).', '[{"key": "A", "text": "0.84 × 0.73"}, {"key": "B", "text": "0.7 × 0.73"}, {"key": "C", "text": "0.3 × 0.73"}, {"key": "D", "text": "0.9 × 0.73"}, {"key": "E", "text": "以上均不对 【注】比赛问题，注意两个点："}]'::jsonb, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 7, true, 19, null),
  ('6150833c-bb94-575d-9ee2-e4ea498e7d3c', '22222222-2222-2222-2222-22222222221c', 'short', '无论采用什么赛制，局数不一定都打完才分胜负；', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 7, true, 20, null),
  ('41cb8538-47a3-5364-b2cb-43e3bf14dd2f', '22222222-2222-2222-2222-22222222221c', 'mcq', '获胜方最后一局是获胜的. 你的坚持，终将美好！ 19 知识咖啡站：（此为自学部分，学有余力的同学自行查看） 一、首次成功型独立试验（几何分布） 如果在1 次试验中，某事件发生的概率是𝑝，那么在独立重复试验中这个 事件在第𝑘次试验才首次发生的概率：(1 −𝑝)𝑘−1𝑝, (𝑘= 0,1,2, ⋯). 例如： 某批产品首次查到不合格品的检查次数的概率. 某射手首次击中目标的射击次数的概率. 掷一颗骰子，首次出现6 点的投掷次数的概率. 同时掷两颗骰子，首次达到两个点数之和为8 的投掷次数的概率. 二、分组问题拔高题 例：某次相亲活动，共有5 名女士和4 名男士参加，活动结束合影时随机 排成一排，则每名男士旁边都有女士的概率是( ).', '[{"key": "A", "text": "41 126"}, {"key": "B", "text": "59 126"}, {"key": "C", "text": "61 126"}, {"key": "D", "text": "65 126"}, {"key": "E", "text": "67 126 你的坚持，终将美好！ 20"}]'::jsonb, '', '要每名男生旁边都有女生，则可以先排女生，再对男生插空
第一步：求总情况数
9个人进行全排列，有A9
9
第二步：排女生
5名女生排成一排有A5
5种方法，此时形成6 个空
第三步：排男生', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 7, true, 21, null),
  ('ed788453-4e37-5685-88c6-1fd3e650b5ac', '22222222-2222-2222-2222-22222222221c', 'short', '4 名男生不相邻，即1,1,1,1 来排， 有A6 4种.4 名男生插入6 个空进行排列，', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 9, true, 22, null),
  ('095e2a84-7a9b-5ecf-a990-1b3c3bea166b', '22222222-2222-2222-2222-22222222221c', 'short', '4 名男生有2 名相邻，即2,1,1 来排 涉及平均分组，先分堆，有 C42C21C11 2! ，2 名男生内部排序2！， 要两边都有女生，这时2 名男生只能插入5 名女生中间的4 个空中， 有C4 1种，剩下的2 名男生插入剩下的5 个空进行排列，有A5 2种 总计有 C42C21C11 2! × 2！× C4 1 × A5 2种', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 9, true, 23, null),
  ('a215eee0-51ea-5a99-8c37-ae33dd696d8b', '22222222-2222-2222-2222-22222222221c', 'short', '4 名男生，其中两两相邻，即2,2 来排 涉及平均分组，先分堆，有 C42C22 2! 种，再2 名男生内部排序2! × 2！种， 要两边都有女生，这时2 组男生只能插入5 名女生中间的4 个空中， 进行排列，有A4 2种，总计有 C42C22 2! × 2！× 2！× A4 2种 第四步：计算 𝑝= A5 5 (A6 4 + C4 2C2 1C1 1 2! × 2！× C4 1 × A5 2 + C4 2C2 2 2! × 2！× 2！× A4 2) A9 9 = 6 × 5 × 4 × 3 + 4 × 3 × 4 × 5 × 4 + 4 × 3 × 4 × 3 9 × 8 × 7 × 6 = 61 126. 你的坚持，终将美好！ 21 你的坚持，终将美好！ 第十二章 数据描述 考点1 平均值 考点2 方差与标准差 考点3 数据的图表表示 你的坚持，终将美好！ 1 考点1：平均值 一、算术平均值 设𝑛个数为𝑥1, 𝑥2, ⋯, 𝑥𝑛，称𝑥̅ = 𝑥1+𝑥2+⋯+𝑥𝑛 𝑛 为这𝑛个数的算术平均数，简记 为 （无比较多重复数据的时候用） 二、加权平均值 设𝑛个数为𝑥1出现𝑓1次，𝑥2出现𝑓2次,⋯,𝑥𝑘出现𝑓𝑘次，且𝑓1 + 𝑓2 + ⋯+ 𝑓𝑘= 𝑛, 称𝑥̅ = 𝑥1𝑓1+𝑥2𝑓2+⋯+𝑥𝑘𝑓𝑘 𝑛 为这𝑛个数的加权平均数.（数据重复出现时使用） 【注】若𝒙𝟏, 𝒙𝟐, ⋯, 𝒙𝒏的平均数为𝒙̅，则𝒌𝒙𝟏+ 𝒃 , 𝒌𝒙𝟐+ 𝒃 , ⋯, 𝒌𝒙𝒏+ 𝒃 的平 均数为𝒌𝒙̅ + 𝒃. 三、众数 在一组数据中，出现次数最多的数据叫做这组数据的众数. 四、中位数 将一组数据按大小依次排列，把处在最中间位置的一个数据(或最中间两个 数据的平均数)叫做这组数据的中位数. 你的坚持，终将美好！ 2 题型1：考查平均值的计算', null, '选（C）.', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 9, true, 24, null),
  ('cc220a23-f970-5e32-8827-dcd96894b5d7', '22222222-2222-2222-2222-22222222221c', 'mcq', '三个自然数𝐴, 𝐵, 𝐶之和是111，已知𝐴, 𝐵的平均数是31，𝐴, 𝐶的平均数 是37，那么𝐵, 𝐶的平均数是( ).', '[{"key": "A", "text": "34"}, {"key": "B", "text": "37"}, {"key": "C", "text": "43"}, {"key": "D", "text": "46"}, {"key": "E", "text": "68"}]'::jsonb, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 13, true, 25, null),
  ('1f637ffa-2684-569b-9741-20015381e37c', '22222222-2222-2222-2222-22222222221c', 'mcq', '为了解某公司员工的年龄结构，按男、女人数的比例进行了随机抽样， 结果如下： 男员工年龄（岁） 23 26 28 30 32 34 36 38 41 女员工年龄（岁） 23 25 27 27 29 31 根据表中数据估计，该公司男员工的平均年龄与全体员工的平均年龄 （单位：岁）分别是( ).', '[{"key": "A", "text": "32,30"}, {"key": "B", "text": "32,29.5"}, {"key": "C", "text": "32,37"}, {"key": "D", "text": "30,27"}, {"key": "E", "text": "29.5,27"}]'::jsonb, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 13, true, 26, null),
  ('8d6f360c-1ff9-5704-9703-2fc9e6fae577', '22222222-2222-2222-2222-22222222221c', 'mcq', '甲、乙、丙三个地区的公务员参加一次测评，其人数和考分情况如表： 三个地区按平均分由高到低的排名顺序为( ).', '[{"key": "A", "text": "乙、丙、甲"}, {"key": "B", "text": "乙、甲、丙"}, {"key": "C", "text": "甲、丙、乙"}, {"key": "D", "text": "丙、甲、乙"}, {"key": "E", "text": "丙、乙、甲"}]'::jsonb, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 15, true, 27, null),
  ('bf582bd8-d08d-5780-9b2d-6a16438985de', '22222222-2222-2222-2222-22222222221c', 'short', '在一组数据𝑥1, 𝑥2, ⋯𝑥𝑛中，各数据与他们的平均数𝑥̅的差的平方的平均数， 叫做这组数据的方差.一般用𝑆2来表示.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 17, true, 28, null),
  ('800cb0f9-bb4f-51ff-84e7-63b54cefbf92', '22222222-2222-2222-2222-22222222221c', 'short', '方差是反映一组数据的整体波动大小的指标，它是指一组数据中各数据 与这组数据的平均数的差的平方的平均数，它反映的是一组数据偏离平 均值的情况. 二、方差计算公式', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 17, true, 29, null),
  ('48cd1015-ba2e-5b76-af1c-f75980ad902f', '22222222-2222-2222-2222-22222222221c', 'short', '基本公式 𝑆2 = 1 𝑛[(𝑥1 −𝑥̅)2 + (𝑥2 −𝑥̅)2 + ⋯+ (𝑥𝑛−𝑥̅)2].', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 17, true, 30, null),
