  ('5c6e375f-045f-5528-842f-bcc695ef7342', '22222222-2222-2222-2222-22222222221c', 'short', '𝑆2 = 1 𝑛[𝑥1 2 + 𝑥2 2 + ⋯+ 𝑥𝑛 2 −𝑛(𝑥̅)2]. 证明 (𝑥1 −𝑥̅)2 + (𝑥2 −𝑥̅)2 + ⋯+ (𝑥𝑛−𝑥̅)2 = 𝑥1 2 −2𝑥1𝑥̅ + 𝑥̅2 + 𝑥2 2 −2𝑥2𝑥̅ + 𝑥̅2 + ⋯+ 𝑥𝑛 2 −2𝑥𝑛𝑥̅ + 𝑥̅2 = 𝑥1 2 + 𝑥2 2 + ⋯+ 𝑥𝑛 2 −2𝑥̅(𝑥1 + 𝑥2 + ⋯+ 𝑥𝑛) + 𝑛𝑥̅2 = 𝑥1 2 + 𝑥2 2 + ⋯+ 𝑥𝑛 2 −2𝑥̅ ⋅𝑛𝑥̅ + 𝑛𝑥̅2 = 𝑥1 2 + 𝑥2 2 + ⋯+ 𝑥𝑛 2 −𝑛𝑥̅2.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 17, true, 32, null),
