  ('5c36e23f-f390-5145-b7c6-deaf2a8ac443', '22222222-2222-2222-2222-22222222221c', 'short', '(𝑎± 𝑏)2 = 𝑎2 ± 2𝑎𝑏+ 𝑏2.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 30, true, 73, null),
  ('19cba994-4887-518c-a509-407f39beeb61', '22222222-2222-2222-2222-22222222221c', 'short', '𝑎2 −𝑏2 = (𝑎−𝑏)(𝑎+ 𝑏).', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 30, true, 74, null),
  ('777ccd00-2ebe-5339-9fdc-6f1c18dd2a36', '22222222-2222-2222-2222-22222222221c', 'short', '(𝑎+ 𝑏+ 𝑐)2 = 𝑎2 + 𝑏2 + 𝑐2 + 2(𝑎𝑏+ 𝑏𝑐+ 𝑎𝑐).', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 30, true, 75, null),
  ('bd42fed0-9897-52eb-9199-b0ceb832fae6', '22222222-2222-2222-2222-22222222221c', 'short', '𝑎3 + 𝑏3 = (𝑎+ 𝑏)(𝑎2 −𝑎𝑏+ 𝑏2).', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 30, true, 76, null),
  ('5a218c54-a17c-5dac-9b46-41d8fe371836', '22222222-2222-2222-2222-22222222221c', 'short', '𝑎3 −𝑏3 = (𝑎−𝑏)(𝑎2 + 𝑎𝑏+ 𝑏2).', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 30, true, 77, null),
  ('1a096685-c099-50f1-a0ad-74f901cf28e3', '22222222-2222-2222-2222-22222222221c', 'short', '(𝑎+ 𝑏)3 = 𝑎3 + 3𝑎2𝑏+ 3𝑎𝑏2 + 𝑏3.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 30, true, 78, null),
  ('5e24bbd1-242a-5d4d-97b0-e3ad97f87e03', '22222222-2222-2222-2222-22222222221c', 'short', '(𝑎−𝑏)3 = 𝑎3 −3𝑎2𝑏+ 3𝑎𝑏2 −𝑏3.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 30, true, 79, null),
  ('28fd91b5-f7e2-5d26-9097-91fedb65cdf7', '22222222-2222-2222-2222-22222222221c', 'short', '裂项相消公式 （1） 1 𝑛(𝑛+𝑘) = 1 𝑘( 1 𝑛− 1 𝑛+𝑘)，特别地 1 𝑛(𝑛+1) = 1 𝑛− 1 𝑛+1和 1 (𝑛−1)𝑛= 1 𝑛−1 − 1 𝑛. （2） 1 (2𝑛−1)(2𝑛+1) = 1 2 ( 1 2𝑛−1 − 1 2𝑛+1). （3） 1 √𝑛+𝑘−√𝑛= 1 𝑘(√𝑛+ 𝑘+ √𝑛)，特别地 1 √𝑛+1+√𝑛= √𝑛+ 1 −√𝑛. 你的坚持，终将美好！ 4', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 30, true, 80, null),
  ('f9633365-c05b-5612-9075-511ed2aa07a4', '22222222-2222-2222-2222-22222222221c', 'short', '恒等变形公式 （1） 1 𝑥1 + 1 𝑥2 = 𝑥1+𝑥2 𝑥1𝑥2', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 31, true, 81, null),
  ('29f31aae-9b10-593e-b85b-9b8e450f961f', '22222222-2222-2222-2222-22222222221c', 'short', '𝑥1 2 + 𝑥2 2 = (𝑥1 + 𝑥2)2 −2𝑥1𝑥2 （3） 1 𝑥12 + 1 𝑥22 = 𝑥12+𝑥22 (𝑥1𝑥2)2 = (𝑥1+𝑥2)2−2𝑥1𝑥2 (𝑥1𝑥2)2', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 31, true, 82, null),
  ('d8077cdd-8760-5785-a6c5-a84a9b6bbe6f', '22222222-2222-2222-2222-22222222221c', 'short', '|𝑥1 −𝑥2| = √(𝑥1 −𝑥2)2 = √(𝑥1 + 𝑥2)2 −4𝑥1𝑥2. （5） 𝐹(𝑥) 𝐺(𝑥) < 0 ⇔𝐹(𝑥)𝐺(𝑥) < 0. （6） 𝐹(𝑥) 𝐺(𝑥) ⩽0 ⇔𝐹(𝑥)𝐺(𝑥) ⩽0, 𝐺(𝑥) ≠0.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 31, true, 83, null),
