  ('c1aecca6-8d72-559d-a7cd-2863a3dbb459', '22222222-2222-2222-2222-22222222221c', 'short', '对正实数𝑎, 𝑏，有 𝑎+𝑏 2 ⩾√𝑎𝑏. 当且仅当𝑎= 𝑏时，等号成立. 一般用变式形式：𝑎+ 𝑏⩾2√𝑎𝑏.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 40, true, 138, null),
  ('f2ca4125-5291-568c-8ef1-d2f7033c5174', '22222222-2222-2222-2222-22222222221c', 'short', '对正实数𝑎, 𝑏，有 𝑎𝑏⩽( 𝑎+𝑏 2 ) 2 . 当且仅当𝑎= 𝑏时，等号成立.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 40, true, 139, null),
