  ('deb17f5a-2841-5cbe-97f0-bf9bce026116', '22222222-2222-2222-2222-22222222221c', 'short', '设𝑎, 𝑏, 𝑐, 𝑑均为实数，则(𝑎2 + 𝑏2)(𝑐2 + 𝑑2) ⩾(𝑎𝑐+ 𝑏𝑑)2，其中等号当 且仅当𝑎𝑑= 𝑏𝑐时成立.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 41, true, 143, null),
  ('c589355e-99f8-5d95-babc-42c84e5886d1', '22222222-2222-2222-2222-22222222221c', 'short', '若𝑎, 𝑏, 𝑐, 𝑑是实数，则√𝑎2 + 𝑏2 + √𝑐2 + 𝑑2 ⩾√(𝑎+ 𝑐)2 + (𝑏+ 𝑑)2. 当且仅当𝑎𝑑= 𝑏𝑐时成立.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 41, true, 144, null),
  ('45e20eb8-1207-5783-b096-f5b87b74c1d5', '22222222-2222-2222-2222-22222222221c', 'short', '数列', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 41, true, 145, null),
  ('5c672d52-11e4-5d6f-8e81-938c37f16be2', '22222222-2222-2222-2222-22222222221c', 'short', '一般数列 𝑆𝑛=𝑎1 + 𝑎2 + 𝑎3 + ⋯+ 𝑎𝑛，则𝑎𝑛= {𝑎1, 𝑛= 1, 𝑆𝑛−𝑆𝑛−1, 𝑛⩾2, ，𝑆1=𝑎1.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 41, true, 146, null),
  ('c21f3e5e-fa73-54bd-9a66-4d7559273af6', '22222222-2222-2222-2222-22222222221c', 'short', '等差数列 ① 𝑎𝑛= 𝑎1 + (𝑛−1)𝑑= 𝑎𝑘+ (𝑛−𝑘)𝑑= 𝑛𝑑+ 𝑎1 −𝑑. ② 若𝑚, 𝑛, 𝑙, 𝑘, (𝑘∈𝑁+)，且𝑚+ 𝑛= 𝑙+ 𝑘，则𝑎𝑚+ 𝑎𝑛= 𝑎𝑙+ 𝑎𝑘. 特别地，若𝑚+ 𝑛= 2𝑝，则𝑎𝑚+ 𝑎𝑛= 𝑎𝑝+ 𝑎𝑝= 2𝑎𝑝. ③ 若等差数列{𝑎𝑛}的公差为𝑑，则数列{𝜆𝑎𝑛± 𝑏}(𝜆, 𝑏为常数)是公差为 𝜆𝑑的等差数列. ④ 𝑆𝑛= (𝑎1+𝑎𝑛)𝑛 2 = 𝑛𝑎1 + 𝑛(𝑛−1) 2 𝑑= 𝑑 2 𝑛2 + (𝑎1 − 𝑑', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 41, true, 147, null),
  ('a16e8436-f101-541e-aaf5-6902da13609a', '22222222-2222-2222-2222-22222222221c', 'short', '𝑛. ⑤ 前𝑛项和𝑆𝑛= 𝐴𝑛2 + 𝐵𝑛 ⇔ 数列{𝑎𝑛}是等差数列. ⑥ 当𝑛为奇数的时候，𝑆𝑛= 𝑛𝑎𝑛+1 2 . 你的坚持，终将美好！ 15', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 41, true, 148, null),
  ('95912dc3-f512-56a0-b4a4-8c54fae0271c', '22222222-2222-2222-2222-22222222221c', 'short', '等比数列 ① 𝑎𝑛= 𝑎1𝑞𝑛−1 = 𝑎𝑚𝑞𝑛−𝑚. ② 𝑆𝑛= { 𝑛𝑎1, 𝑞= 1, 𝑎1(1−𝑞𝑛) 1−𝑞 = 𝑎1−𝑎1𝑞𝑛 1−𝑞 = 𝑎1−𝑎𝑛𝑞 1−𝑞 , 𝑞≠0 且𝑞≠1. ③ 若𝑚, 𝑛, 𝑙, 𝑘, (𝑘∈𝑁+)，且𝑚+ 𝑛= 𝑙+ 𝑘，则𝑎𝑚⋅𝑎𝑛= 𝑎𝑙⋅𝑎𝑘. 特别地，若𝑚+ 𝑛= 2𝑝，则𝑎𝑚⋅𝑎𝑛= 𝑎𝑝⋅𝑎𝑝= (𝑎𝑝)2. ④ 若数列{𝑎𝑛}是公比为𝑞1的等比数列，若数列{𝑏𝑛}是公比为𝑞2的等比数 列，则{𝜆1𝑎𝑛∙𝜆2𝑏𝑛}(𝜆1, 𝜆2为常数)也是等比数列且公比为𝑞1 ∙𝑞2. ⑤ 一个数列既是等差数列又是等比数列，则该数列为非零常数列.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 42, true, 149, null),
